/* Palabra 0.5b.5 – 50 reading-comprehension mini dialogues, SRS independent. */
window.PalabraDialogues=(()=>{'use strict';
const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const lessons=[{"id":"basis1-1","title":"¡Hola! ¿Qué tal?","subtitle":"Basis 1 · Paket 1","required":1,"description":"Ein erstes Kennenlernen verstehen.","lines":[["Lucía","¡Hola! ¡Buenos días!","Hallo! Guten Morgen!"],["Daniel","¡Hola! ¿Qué tal?","Hallo! Wie geht’s?"],["Lucía","Muy bien, gracias. ¿Y tú?","Sehr gut, danke. Und dir?"],["Daniel","Bien, gracias. Me llamo Daniel. ¿Cómo te llamas?","Gut, danke. Ich heiße Daniel. Wie heißt du?"],["Lucía","Me llamo Lucía. ¡Mucho gusto!","Ich heiße Lucía. Freut mich!"],["Daniel","¡Igualmente! ¡Hasta luego!","Ganz meinerseits! Bis später!"],["Lucía","¡Adiós!","Auf Wiedersehen!"]],"questions":[{"q":"Wie geht es Lucía?","choices":["Sehr gut.","Nicht besonders gut.","Das erzählt sie nicht."],"correct":0,"why":"Lucía sagt „Muy bien, gracias.“ – ihr geht es sehr gut."},{"q":"Was erfährt Lucía über Daniel?","choices":["Er wohnt in Madrid.","Er heißt Daniel.","Er ist 27 Jahre alt."],"correct":1,"why":"Daniel stellt sich mit „Me llamo Daniel“ vor."},{"q":"Was passiert am Ende des Gesprächs?","choices":["Sie verabreden sich.","Sie fragen nach dem Alter.","Sie verabschieden sich."],"correct":2,"why":"„¡Hasta luego!“ und „¡Adiós!“ sind Verabschiedungen."}],"tips":[{"title":"¿Qué tal?","body":"Wörtlich: keine saubere Wort-für-Wort-Übersetzung; „qué“ heißt „was/welch“, „tal“ etwa „so/solch“. Natürlich: „Wie geht’s?“ oder „Wie läuft’s?“ Merke dir ¿Qué tal? am besten als feste Begrüßung."},{"title":"Me llamo …","body":"Wörtlich: „Ich nenne mich …“ (me = mich, llamo = ich nenne/rufe). Natürlich: „Ich heiße …“. Spanisch formuliert den Namen als Handlung, die man auf sich selbst bezieht."},{"title":"¡Hasta luego!","body":"Wörtlich und natürlich: „Bis später!“ (hasta = bis, luego = später). Eine Verabschiedung, keine Aussage darüber, ob ihr euch wirklich heute noch seht."}]},{"id":"basis1-2","title":"¿De dónde eres?","subtitle":"Basis 1 · Paket 2","required":2,"description":"Herkunft, Wohnort und Alter auseinanderhalten.","lines":[["Carlos","¡Hola! Me llamo Carlos. ¿Cómo te llamas?","Hallo! Ich heiße Carlos. Wie heißt du?"],["Ana","¡Hola! Me llamo Ana. ¡Mucho gusto!","Hallo! Ich heiße Ana. Freut mich!"],["Carlos","¡Igualmente! ¿De dónde eres?","Ganz meinerseits! Woher kommst du?"],["Ana","Soy de Alemania. ¿Y tú?","Ich komme aus Deutschland. Und du?"],["Carlos","Soy de España. Vivo en Madrid. ¿Dónde vives?","Ich komme aus Spanien. Ich wohne in Madrid. Wo wohnst du?"],["Ana","Vivo en Berlín.","Ich wohne in Berlin."],["Carlos","¡Qué bien! ¿Cuántos años tienes?","Wie schön! Wie alt bist du?"],["Ana","Tengo 27 años.","Ich bin 27 Jahre alt."],["Carlos","¡Mucho gusto, Ana! ¡Hasta luego!","Freut mich, Ana! Bis später!"]],"questions":[{"q":"Woher kommt Ana?","choices":["Aus Spanien.","Aus Deutschland.","Aus Madrid."],"correct":1,"why":"Ana sagt „Soy de Alemania“ – sie kommt aus Deutschland."},{"q":"Welche Aussage stimmt?","choices":["Carlos kommt aus Deutschland.","Ana wohnt in Madrid.","Carlos wohnt in Madrid."],"correct":2,"why":"Carlos sagt „Vivo en Madrid“. Ana wohnt dagegen in Berlin."},{"q":"Wie alt ist Ana?","choices":["27 Jahre.","20 Jahre.","Das wird nicht erwähnt."],"correct":0,"why":"„Tengo 27 años“ bedeutet „Ich bin 27 Jahre alt“. Die Zahl ist hier bewusst als Ziffer dargestellt."},{"q":"Was ist der Unterschied zwischen „Soy de …“ und „Vivo en …“?","choices":["Das eine nennt die Herkunft, das andere den Wohnort.","Beide bedeuten genau dasselbe.","Das eine nennt das Alter, das andere den Namen."],"correct":0,"why":"„Soy de …“ = Ich komme aus …; „Vivo en …“ = Ich wohne in …"}],"tips":[{"title":"Soy de … / Vivo en …","body":"Wörtlich: „Ich bin aus Deutschland“ (soy de Alemania) und „Ich lebe in Berlin“ (vivo en Berlín). Natürlich: „Ich komme aus Deutschland“ und „Ich wohne in Berlin“. Herkunft und Wohnort werden unterschiedlich ausgedrückt."},{"title":"Tengo 27 años","body":"Wörtlich: „Ich habe 27 Jahre.“ Natürlich: „Ich bin 27 Jahre alt.“ Spanisch „hat“ das Alter mit tener, statt „alt zu sein“. Ein tolles Beispiel dafür, dass Sprachen unterschiedlich denken."},{"title":"¿Y tú?","body":"Wörtlich und natürlich: „Und du?“ Das Pronomen tú macht deutlich, dass du die Frage an dein Gegenüber zurückgibst."}]},{"id":"basis1-3","title":"Un café, por favor","subtitle":"Basis 1 · Paket 3","required":3,"description":"Eine erste Bestellung verstehen.","lines":[["Camarera","¡Hola! ¿Qué quieres?","Hallo! Was möchtest du?"],["Cliente","Quiero un café con leche y una tostada, por favor.","Ich möchte einen Milchkaffee und einen Toast, bitte."],["Camarera","¿Algo más?","Noch etwas?"],["Cliente","Un agua para mí también, por favor.","Für mich auch noch ein Wasser, bitte."],["Camarera","Muy bien.","Sehr gut."],["Cliente","Gracias. Nada más.","Danke. Sonst nichts."]],"questions":[{"q":"Was bestellt die Person zu essen?","choices":["Einen Toast.","Ein Bocadillo.","Einen Kuchen."],"correct":0,"why":"„Una tostada“ ist ein Toast."},{"q":"Welche Getränke bestellt die Person?","choices":["Tee und Saft.","Kaffee mit Milch und Wasser.","Nur Wasser."],"correct":1,"why":"„Un café con leche“ und „un agua“."},{"q":"Möchte die Person am Ende noch mehr bestellen?","choices":["Ja, noch ein Bocadillo.","Sie fragt nach der Rechnung.","Nein, sie sagt „Nada más“."],"correct":2,"why":"„Nada más“ heißt „Sonst nichts“."}],"tips":[{"title":"Quiero…","body":"Wörtlich: „Ich will …“ Natürlich beim Bestellen oft: „Ich möchte …“. Quiero ist direkt, aber im spanischen Alltag häufig ganz normal. Mit por favor klingt es freundlicher."},{"title":"Un agua","body":"Wörtlich und natürlich: „Ein Wasser.“ Überraschung: agua ist weiblich (la misma agua), bekommt aber unmittelbar davor im Singular un/el, weil das erste a betont ist. Es bleibt grammatisch weiblich."}]},{"id":"basis1-4","title":"¿Con hielo o sin hielo?","subtitle":"Basis 1 · Paket 4","required":4,"description":"Alternativen und Bezahlung verstehen.","lines":[["Camarero","¡Buenos días! ¿Qué quieres?","Guten Morgen! Was möchtest du?"],["Cliente","⟦Querría⟧ un zumo frío, por favor.","Ich hätte gerne einen kalten Saft, bitte."],["Camarero","¿Con hielo o sin hielo?","Mit oder ohne Eiswürfel?"],["Cliente","Sin hielo, gracias. ¿Tienes bocadillos?","Ohne Eis, danke. Hast du belegte Baguettes?"],["Camarero","No tenemos bocadillos, pero tenemos tostadas.","Wir haben keine belegten Baguettes, aber wir haben Toast."],["Cliente","Prefiero una tostada. ¿Cuánto cuesta?","Ich hätte lieber einen Toast. Wie viel kostet er?"],["Camarero","Dos euros.","Zwei Euro."],["Cliente","Muy bien. ¿Puedo pagar con tarjeta?","Sehr gut. Kann ich mit Karte bezahlen?"],["Camarero","Sí, claro.","Ja, natürlich."]],"questions":[{"q":"Warum bestellt die Person eine Tostada?","choices":["Weil es keine Bocadillos gibt.","Weil sie keinen Hunger hat.","Weil Toast kostenlos ist."],"correct":0,"why":"Der Kellner sagt „No tenemos bocadillos, pero tenemos tostadas“."},{"q":"Wie möchte die Person ihren Saft?","choices":["Heiß und mit Zucker.","Kalt und ohne Eiswürfel.","Groß und mit Milch."],"correct":1,"why":"„Un zumo frío“ und „Sin hielo“."},{"q":"Wie bezahlt die Person?","choices":["Bar.","Mit einem Gutschein.","Mit Karte."],"correct":2,"why":"„¿Puedo pagar con tarjeta?“ bedeutet „Kann ich mit Karte bezahlen?“"}],"tips":[{"title":"Querría…","body":"Wörtlich/sinngemäß: „Ich würde wollen …“. Natürlich: „Ich hätte gerne …“. Querría ist der Condicional von querer und klingt höflicher als quiero. Die Zeitform musst du noch nicht beherrschen."},{"title":"Prefiero…","body":"Wörtlich: „Ich bevorzuge …“. Natürlich im Café: „Ich hätte lieber …“. Prefiero kommt von preferir; die Stammänderung e → ie sieht man in dieser Form."}]},{"id":"basis1-5","title":"Un plan para mañana","subtitle":"Basis 1 · Paket 5","required":5,"description":"Einen Termin vereinbaren.","lines":[["Lucía","¡Hola, Carlos! ¿Qué tal?","Hallo, Carlos! Wie geht’s?"],["Carlos","¡Muy bien! ¿Y tú?","Sehr gut! Und dir?"],["Lucía","Bien, gracias. ¿Tienes tiempo mañana?","Gut, danke. Hast du morgen Zeit?"],["Carlos","Sí, mañana tengo tiempo.","Ja, morgen habe ich Zeit."],["Lucía","¿Quieres venir al café mañana por la tarde?","Möchtest du morgen Nachmittag ins Café kommen?"],["Carlos","Sí, mañana por la tarde tengo tiempo.","Ja, morgen Nachmittag habe ich Zeit."],["Lucía","¡Sí! Vamos al café mañana.","Ja! Wir gehen morgen ins Café."],["Carlos","¡Muy bien! ¡Hasta mañana!","Sehr gut! Bis morgen!"]],"questions":[{"q":"Wann schlägt Lucía das Treffen vor?","choices":["Heute Nachmittag.","Morgen Nachmittag.","Am Sonntag."],"correct":1,"why":"Lucía fragt: „¿Quieres venir al café mañana por la tarde?“"},{"q":"Hat Carlos morgen Zeit?","choices":["Ja.","Nein.","Er weiß es nicht."],"correct":0,"why":"Carlos antwortet: „Sí, mañana por la tarde tengo tiempo.“"},{"q":"Wohin wollen die beiden gehen?","choices":["In den Park.","Zum Bahnhof.","Ins Café."],"correct":2,"why":"„Vamos al café mañana“ – morgen gehen sie ins Café."}],"tips":[{"title":"Vamos al café","body":"Wörtlich: „Wir gehen zum Café.“ Natürlich: „Wir gehen ins Café.“ al ist a + el („zu dem“). Achtung: vamos a + Infinitiv ist etwas anderes: Vamos a tomar un café = „Wir werden/ wollen einen Kaffee trinken“."}]},{"id":"basis1-6","title":"Mejor a las cinco","subtitle":"Basis 1 · Paket 6","required":6,"description":"Eine Planänderung verstehen.","lines":[["Carlos","¡Hola, Lucía! ¿Tienes tiempo el sábado?","Hallo, Lucía! Hast du am Samstag Zeit?"],["Lucía","Sí, ¿quieres quedar?","Ja, möchtest du dich treffen?"],["Carlos","¡Sí! ¿A las cuatro?","Ja! Um vier Uhr?"],["Lucía","A las cuatro no puedo. Mejor a las cinco.","Um vier kann ich nicht. Lieber um fünf."],["Carlos","Perfecto. ¿Dónde quedamos?","Perfekt. Wo treffen wir uns?"],["Lucía","Delante del café, cerca del parque.","Vor dem Café, in der Nähe des Parks."],["Carlos","¡Muy bien! El sábado a las cinco.","Sehr gut! Samstag um fünf."]],"questions":[{"q":"Welche Uhrzeit schlägt Carlos zuerst vor?","choices":["Vier Uhr.","Fünf Uhr.","Halb fünf."],"correct":0,"why":"„¿A las cuatro?“ heißt „Um vier Uhr?“"},{"q":"Warum wird die Zeit geändert?","choices":["Das Café hat geschlossen.","Lucía kann um vier nicht.","Carlos muss arbeiten."],"correct":1,"why":"Lucía sagt „A las cuatro no puedo“."},{"q":"Wo treffen sie sich?","choices":["Im Park.","Am Bahnhof.","Vor dem Café nahe dem Park."],"correct":2,"why":"„Delante del café, cerca del parque“."}],"tips":[{"title":"Delante del café","body":"Wörtlich: „vor dem Café“. Delante de = vor; de + el verschmilzt zu del. Deshalb sagt man delante del café und nicht delante de el café."},{"title":"¿A las cuatro?","body":"Wörtlich und natürlich: „Um vier?“ a bedeutet hier „um“, las cuatro heißt „die vier [Stunden]“. Ausnahme: a la una = um ein Uhr."}]},{"id":"basis1-7","title":"Una foto de familia","subtitle":"Basis 1 · Paket 7","required":7,"description":"Familienbeziehungen verstehen.","lines":[["Lucía","¡Hola, Carlos! ¿Quién es ella?","Hallo, Carlos! Wer ist sie?"],["Carlos","Es mi hermana. Se llama Elena.","Das ist meine Schwester. Sie heißt Elena."],["Lucía","¡Qué bonito! ¿Y este?","Wie schön! Und wer ist dieser hier?"],["Carlos","Es mi hermano, Pablo. Es muy divertido.","Das ist mein Bruder Pablo. Er ist sehr lustig."],["Lucía","¿Y tus padres?","Und deine Eltern?"],["Carlos","Viven en Alemania. Mi madre es muy simpática.","Sie wohnen in Deutschland. Meine Mutter ist sehr nett."],["Lucía","¡Qué familia tan simpática!","Was für eine nette Familie!"]],"questions":[{"q":"Wer ist Elena?","choices":["Carlos’ Mutter.","Carlos’ Schwester.","Carlos’ Freundin."],"correct":1,"why":"„Es mi hermana. Se llama Elena.“"},{"q":"Wie beschreibt Carlos seinen Bruder?","choices":["Als lustig.","Als sehr ernst.","Als schüchtern."],"correct":0,"why":"„Es muy divertido“ heißt „Er ist sehr lustig“."},{"q":"Wo wohnen Carlos’ Eltern?","choices":["In Madrid.","In Mexiko.","In Deutschland."],"correct":2,"why":"„Viven en Alemania“ bedeutet „Sie wohnen in Deutschland“."}],"tips":[{"title":"Es mi hermana","body":"Wörtlich: „Ist meine Schwester“ – das Subjekt „das/sie“ wird im Spanischen oft nicht ausgesprochen. Natürlich: „Das ist meine Schwester.“ Es ist eine Form von ser."},{"title":"Viven en Alemania","body":"Wörtlich: „[Sie] leben in Deutschland.“ Natürlich je nach Kontext: „Sie wohnen in Deutschland.“ Die Endung -en zeigt die Mehrzahl, auch ohne ausgesprochenes „sie“."},{"title":"¡Qué familia tan simpática!","body":"Wörtlich ungefähr: „Was für eine so nette Familie!“ Natürlich: „Was für eine nette Familie!“ Qué … tan … verstärkt hier das Staunen."}]},{"id":"basis1-8","title":"Nuestros pasatiempos","subtitle":"Basis 1 · Paket 8","required":8,"description":"Interessen und Gemeinsamkeiten erkennen.","lines":[["Carlos","Lucía, ¿qué te gusta hacer en tu tiempo libre?","Lucía, was machst du gerne in deiner Freizeit?"],["Lucía","Me gusta escuchar música y bailar. ¿Y a ti?","Ich höre gerne Musik und tanze gerne. Und du?"],["Carlos","Me gusta jugar al fútbol y leer libros.","Ich spiele gerne Fußball und lese Bücher."],["Lucía","¿Juegas al fútbol todos los días?","Spielst du jeden Tag Fußball?"],["Carlos","No, normalmente juego el sábado. A veces también cocino con mi hermana.","Nein, normalerweise spiele ich samstags. Manchmal koche ich auch mit meiner Schwester."],["Lucía","¡Qué bien! A mí me gusta cocinar también.","Wie schön! Ich koche auch gerne."],["Carlos","¿Por qué te gusta cocinar?","Warum kochst du gerne?"],["Lucía","Porque es divertido.","Weil es Spaß macht."]],"questions":[{"q":"Welche Hobbys nennt Lucía zuerst?","choices":["Fußball und Lesen.","Musik hören und Tanzen.","Kochen und Wandern."],"correct":1,"why":"„Escuchar música y bailar“."},{"q":"Wann spielt Carlos normalerweise Fußball?","choices":["Jeden Tag.","Nie.","Samstags."],"correct":2,"why":"„Normalmente juego el sábado“."},{"q":"Welche Gemeinsamkeit entdecken die beiden?","choices":["Beide kochen gerne.","Beide tanzen gerne.","Beide spielen Fußball."],"correct":0,"why":"Carlos kocht manchmal; Lucía sagt, dass sie ebenfalls gerne kocht."}],"tips":[{"title":"Me gusta bailar","body":"Wörtlich: „Tanzen gefällt mir.“ Natürlich: „Ich tanze gern.“ Das Besondere: Im Spanischen ist das Tanzen das, was gefällt – nicht „ich“ das Subjekt."},{"title":"Juego / juegas","body":"Wörtlich und natürlich: juego = „ich spiele“, juegas = „du spielst“. Im Infinitiv heißt das Verb jugar. Beim Konjugieren wird u zu ue."}]},{"id":"basis1-9","title":"¿Dónde está la farmacia?","subtitle":"Basis 1 · Paket 9","required":9,"description":"Orte und Richtungen verstehen.","lines":[["Carlos","Perdón, ¿dónde está la farmacia?","Entschuldigung, wo ist die Apotheke?"],["Mujer","Está cerca, en esta calle.","Sie ist in der Nähe, in dieser Straße."],["Carlos","¿A la derecha o a la izquierda?","Rechts oder links?"],["Mujer","Todo recto y después a la derecha.","Immer geradeaus und danach rechts."],["Carlos","¿Está al lado del supermercado?","Ist sie neben dem Supermarkt?"],["Mujer","No, está enfrente del supermercado.","Nein, sie ist gegenüber vom Supermarkt."],["Carlos","¡Muchas gracias!","Vielen Dank!"],["Mujer","¡De nada!","Gern geschehen!"]],"questions":[{"q":"Was sucht Carlos?","choices":["Den Supermarkt.","Die Apotheke.","Den Bahnhof."],"correct":1,"why":"„¿Dónde está la farmacia?“"},{"q":"Wohin muss Carlos nach dem Geradeausgehen?","choices":["Nach links.","Zurück.","Nach rechts."],"correct":2,"why":"„Todo recto y después a la derecha“."},{"q":"Wo liegt die Apotheke?","choices":["Gegenüber vom Supermarkt.","Neben dem Supermarkt.","Im Supermarkt."],"correct":0,"why":"„Enfrente del supermercado“ heißt „gegenüber vom Supermarkt“."}],"tips":[{"title":"¿Dónde está…?","body":"Wörtlich und natürlich: „Wo ist …?“ Está fragt nach dem Standort einer bestimmten Sache. ¿Dónde está la farmacia? = „Wo ist die Apotheke?“"},{"title":"Al lado del supermercado","body":"Wörtlich: „an der Seite des Supermarkts“. Natürlich: „neben dem Supermarkt“. al lado de bedeutet „neben“; de + el wird del."}]},{"id":"basis1-10","title":"El camino a la estación","subtitle":"Basis 1 · Paket 10","required":10,"description":"Wegbeschreibung und Nachfragen verstehen.","lines":[["Lucía","Perdón, ¿cómo llego a la estación?","Entschuldigung, wie komme ich zum Bahnhof?"],["Hombre","Tienes que seguir todo recto, cruzar la calle y girar a la izquierda en el semáforo.","Du musst geradeaus weitergehen, die Straße überqueren und an der Ampel links abbiegen."],["Lucía","Perdón, no entiendo. ¿Puedes repetir más despacio?","Entschuldigung, ich verstehe nicht. Kannst du das langsamer wiederholen?"],["Hombre","Sí, claro. Primero, todo recto. Después, cruza la calle. En el semáforo, a la izquierda.","Ja, natürlich. Zuerst geradeaus. Danach überquere die Straße. An der Ampel links."],["Lucía","Gracias. ¿Está lejos?","Danke. Ist es weit?"],["Hombre","No, está cerca. Puedes ir a pie.","Nein, es ist nah. Du kannst zu Fuß gehen."],["Lucía","¡Muchas gracias!","Vielen Dank!"],["Hombre","¡De nada! ¡Hasta luego!","Gern geschehen! Bis später!"]],"questions":[{"q":"Wohin möchte Lucía?","choices":["Zur Haltestelle.","Zum Bahnhof.","Zur Apotheke."],"correct":1,"why":"„¿Cómo llego a la estación?“"},{"q":"Warum bittet Lucía um eine Wiederholung?","choices":["Sie versteht die Erklärung nicht.","Sie möchte mit dem Bus fahren.","Sie hat keine Zeit."],"correct":0,"why":"„No entiendo. ¿Puedes repetir más despacio?“"},{"q":"Was muss sie an der Ampel tun?","choices":["Rechts abbiegen.","Stehen bleiben.","Links abbiegen."],"correct":2,"why":"„En el semáforo, a la izquierda“."},{"q":"Wie kann sie zum Bahnhof gelangen?","choices":["Nur mit dem Zug.","Zu Fuß.","Nur mit dem Bus."],"correct":1,"why":"„Puedes ir a pie“ = Du kannst zu Fuß gehen."}],"tips":[{"title":"Tienes que seguir…","body":"Wörtlich ungefähr: „Du hast zu folgen/weiterzugehen …“. Natürlich: „Du musst weitergehen …“. tener que + Infinitiv drückt eine Notwendigkeit aus."},{"title":"Cruza la calle","body":"Wörtlich und natürlich: „Überquere die Straße!“ Cruza ist eine direkte Aufforderung an eine Person (tú), der Imperativ von cruzar."},{"title":"Hay / está","body":"Wörtlich: hay = „es gibt / es ist vorhanden“; está = „[es] befindet sich“. Natürlich: Hay un banco = „Da ist eine Bank“; El banco está aquí = „Die Bank ist hier“. Erst Existenz, dann Ort."}]},{"id":"basis2-1","title":"Una mañana normal","subtitle":"Basis 2 · Paket 1","required":1,"deck_id":"palabra-basis-2","description":"Eine Morgenroutine verstehen.","lines":[["Ana","¡Buenos días, Pablo! ¿A qué hora te levantas normalmente?","Guten Morgen, Pablo! Um wie viel Uhr stehst du normalerweise auf?"],["Pablo","Me despierto a las siete, pero me levanto a las siete y media.","Ich wache um sieben auf, stehe aber erst um halb acht auf."],["Ana","¿Y qué haces después?","Und was machst du danach?"],["Pablo","Primero me ducho, luego me visto y desayuno.","Zuerst dusche ich, dann ziehe ich mich an und frühstücke."],["Ana","Yo desayuno antes de ducharme. ¿Y por la noche?","Ich frühstücke vor dem Duschen. Und abends?"],["Pablo","Normalmente me acuesto temprano, pero a veces no puedo dormirme.","Normalerweise gehe ich früh ins Bett, aber manchmal kann ich nicht einschlafen."]],"questions":[{"q":"Wann steht Pablo auf?","choices":["Um sieben Uhr.","Um halb acht.","Um acht Uhr."],"correct":1,"why":"Er wacht um sieben auf, steht aber um halb acht auf."},{"q":"Was macht Pablo zuerst nach dem Aufstehen?","choices":["Er duscht.","Er frühstückt.","Er geht ins Bett."],"correct":0,"why":"„Primero me ducho“ – zuerst duscht er."},{"q":"Was unterscheidet Anas Routine von Pablos?","choices":["Ana frühstückt vor dem Duschen.","Ana steht erst mittags auf.","Ana duscht nie."],"correct":0,"why":"Ana sagt: „Yo desayuno antes de ducharme.“"}],"tips":[{"title":"Me levanto","body":"Wörtlich: „Ich erhebe mich.“ Natürlich: „Ich stehe auf.“ Levantar heißt „heben/erheben“; mit me richtet sich die Handlung auf mich selbst. Das Bild „ich hebe mich aus dem Bett“ macht das reflexive Verb leichter merkbar."}]},{"id":"basis2-2","title":"Un día muy ocupado","subtitle":"Basis 2 · Paket 2","required":2,"deck_id":"palabra-basis-2","description":"Einen anstrengenden Tag nachvollziehen.","lines":[["Ana","¿Qué tal tu día, Pablo?","Wie war dein Tag, Pablo?"],["Pablo","Estoy muy cansado. Hoy tengo que trabajar y estudiar.","Ich bin sehr müde. Heute muss ich arbeiten und lernen."],["Ana","¿A qué hora terminas?","Wann bist du fertig?"],["Pablo","Termino a las seis. Después vuelvo a casa y descanso un poco.","Ich bin um sechs fertig. Danach gehe ich nach Hause und ruhe mich etwas aus."],["Ana","¿Cenas temprano?","Isst du früh zu Abend?"],["Pablo","Casi siempre. Pero hoy tengo mucho que hacer y voy a cenar más tarde.","Fast immer. Aber heute habe ich viel zu tun und werde später zu Abend essen."],["Ana","Entonces, ¡que descanses!","Dann ruh dich gut aus!"]],"questions":[{"q":"Warum ist Pablo müde?","choices":["Er hat viel zu tun.","Er war auf einer Party.","Er hat den Zug verpasst."],"correct":0,"why":"Er muss heute arbeiten und lernen."},{"q":"Wann endet sein Arbeitstag?","choices":["Um vier.","Um fünf.","Um sechs."],"correct":2,"why":"„Termino a las seis.“"},{"q":"Was ist heute anders als sonst?","choices":["Er frühstückt nicht.","Er isst später zu Abend.","Er schläft mittags."],"correct":1,"why":"Normalerweise isst er früh, heute aber später."}],"tips":[{"title":"Tengo que trabajar","body":"Wörtlich ungefähr: „Ich habe zu arbeiten.“ Natürlich: „Ich muss arbeiten.“ Tener heißt „haben“; tener que + Infinitiv wird im Spanischen zur Pflicht oder Notwendigkeit."}]},{"id":"basis2-3","title":"La lista de la compra","subtitle":"Basis 2 · Paket 3","required":3,"deck_id":"palabra-basis-2","description":"Eine Einkaufsliste verstehen.","lines":[["Marta","Voy al supermercado. ¿Necesitamos algo?","Ich gehe zum Supermarkt. Brauchen wir etwas?"],["Diego","Sí, necesitamos pan, queso y huevos.","Ja, wir brauchen Brot, Käse und Eier."],["Marta","¿Y fruta?","Und Obst?"],["Diego","Tenemos plátanos, pero no tenemos manzanas.","Wir haben Bananen, aber keine Äpfel."],["Marta","Perfecto. Voy a comprar manzanas también.","Perfekt. Ich werde auch Äpfel kaufen."],["Diego","Gracias. ¿Tienes la lista de la compra?","Danke. Hast du die Einkaufsliste?"],["Marta","¡Sí! Está aquí, en mi bolsa.","Ja! Sie ist hier in meiner Tasche."]],"questions":[{"q":"Welches Obst haben die beiden bereits?","choices":["Äpfel.","Bananen.","Orangen."],"correct":1,"why":"„Tenemos plátanos“ – sie haben Bananen."},{"q":"Was muss Marta zusätzlich kaufen?","choices":["Äpfel.","Fisch.","Tomaten."],"correct":0,"why":"Es fehlen Äpfel."},{"q":"Wo ist die Einkaufsliste?","choices":["Im Kühlschrank.","Auf dem Tisch.","In Martas Tasche."],"correct":2,"why":"„Está aquí, en mi bolsa.“"}],"tips":[{"title":"Necesitamos","body":"Wörtlich und natürlich: „Wir brauchen“. Das Grundverb heißt necesitar („brauchen/benötigen“). Die Endung -amos verrät hier „wir“, selbst wenn nosotros nicht dasteht."}]},{"id":"basis2-4","title":"Una oferta especial","subtitle":"Basis 2 · Paket 4","required":4,"deck_id":"palabra-basis-2","description":"Eine Kaufentscheidung verstehen.","lines":[["Cliente","Buenos días. ¿Cuánto cuesta un kilo de tomates?","Guten Tag. Was kostet ein Kilo Tomaten?"],["Vendedora","Tres euros. Pero hoy tenemos una oferta: dos kilos por cinco euros.","Drei Euro. Aber heute haben wir ein Angebot: zwei Kilo für fünf Euro."],["Cliente","Gracias, pero dos kilos son demasiado. ⟦Querría⟧ medio kilo.","Danke, aber zwei Kilo sind zu viel. Ich hätte gerne ein halbes Kilo."],["Vendedora","Perfecto. ¿Algo más?","Perfekt. Sonst noch etwas?"],["Cliente","Sí, un paquete de arroz. ¿Es caro?","Ja, eine Packung Reis. Ist sie teuer?"],["Vendedora","No, es barato. Cuesta dos euros.","Nein, sie ist günstig. Sie kostet zwei Euro."],["Cliente","Muy bien. ⟦Me llevo uno⟧.","Sehr gut. Ich nehme eine."]],"questions":[{"q":"Warum nimmt die Person nicht zwei Kilo Tomaten?","choices":["Weil das zu viel ist.","Weil die Tomaten schlecht sind.","Weil es keine Tomaten gibt."],"correct":0,"why":"„Dos kilos son demasiado.“"},{"q":"Wie viel kostet der Reis?","choices":["Drei Euro.","Fünf Euro.","Zwei Euro."],"correct":2,"why":"„Cuesta dos euros.“"},{"q":"Was entscheidet die Person am Ende?","choices":["Sie nimmt eine Packung Reis.","Sie geht ohne Einkauf.","Sie bestellt Kaffee."],"correct":0,"why":"„Me llevo uno“ bedeutet „Ich nehme eins“."}],"tips":[{"title":"Querría","body":"Wörtlich/sinngemäß: „Ich würde wollen“. Natürlich: „Ich hätte gerne“. Das ist der höfliche Condicional von querer. Du kannst die Form direkt als freundliche Bestellung benutzen."},{"title":"Me llevo uno","body":"Wörtlich: „Ich nehme mir eins mit.“ Natürlich beim Einkaufen: „Ich nehme eins.“ Llevar bedeutet „tragen/mitnehmen“, me markiert hier die Beteiligung der sprechenden Person."}]},{"id":"basis2-5","title":"Mi nuevo piso","subtitle":"Basis 2 · Paket 5","required":5,"deck_id":"palabra-basis-2","description":"Eine Wohnung kennenlernen.","lines":[["Elena","¡Bienvenido a mi nuevo piso!","Willkommen in meiner neuen Wohnung!"],["Pablo","¡Qué bonito! ¿Vives aquí con tu pareja?","Wie schön! Wohnst du hier mit deinem Partner oder deiner Partnerin?"],["Elena","Sí. Este es el salón y allí está la cocina.","Ja. Das ist das Wohnzimmer, und dort ist die Küche."],["Pablo","¿Y dónde está el dormitorio?","Und wo ist das Schlafzimmer?"],["Elena","Al lado del baño. Mira, esta es la habitación.","Neben dem Badezimmer. Schau, das ist das Zimmer."],["Pablo","¿Y tienes una mesa en el salón?","Und hast du einen Tisch im Wohnzimmer?"],["Elena","Sí, hay una mesa pequeña al lado de la ventana.","Ja, es gibt einen kleinen Tisch neben dem Fenster."]],"questions":[{"q":"Mit wem wohnt Elena?","choices":["Mit ihrem Bruder.","Mit ihrer Partnerperson.","Allein."],"correct":1,"why":"Sie bestätigt: „¿Vives aquí con tu pareja?“ – „Sí.“"},{"q":"Wo ist das Schlafzimmer?","choices":["Neben dem Badezimmer.","Auf dem Balkon.","Neben der Küche."],"correct":0,"why":"„Al lado del baño.“"},{"q":"Was steht am Fenster?","choices":["Ein Sofa.","Ein Schrank.","Ein kleiner Tisch."],"correct":2,"why":"„Una mesa pequeña al lado de la ventana.“"}],"tips":[{"title":"Hay / está","body":"Wörtlich: hay = „es gibt“; está = „[es] befindet sich“. Natürlich: Hay una mesa = „Da steht ein Tisch“. La mesa está al lado de la ventana = „Der Tisch steht neben dem Fenster“. Erst wird etwas eingeführt, dann sein Ort genannt."}]},{"id":"basis2-6","title":"¿Dónde están mis llaves?","subtitle":"Basis 2 · Paket 6","required":6,"deck_id":"palabra-basis-2","description":"Einen verlorenen Gegenstand finden.","lines":[["Diego","Marta, ¡no encuentro mis llaves!","Marta, ich finde meine Schlüssel nicht!"],["Marta","¿Están encima de la mesa?","Liegen sie auf dem Tisch?"],["Diego","No. Tampoco están en el armario.","Nein. Im Schrank sind sie auch nicht."],["Marta","¿⟦Has mirado⟧ debajo del sofá?","Hast du unter dem Sofa nachgesehen?"],["Diego","Un momento… ¡Sí! Están aquí, debajo del sofá.","Einen Moment … Ja! Sie sind hier, unter dem Sofa."],["Marta","¡Perfecto! Y después, ¿puedes sacar la basura?","Perfekt! Und kannst du danach den Müll rausbringen?"],["Diego","Sí, claro. Primero guardo las llaves.","Ja, klar. Zuerst räume ich die Schlüssel weg."]],"questions":[{"q":"Was sucht Diego?","choices":["Seine Schuhe.","Seine Schlüssel.","Sein Handy."],"correct":1,"why":"„No encuentro mis llaves.“"},{"q":"Wo liegen die Schlüssel?","choices":["Unter dem Sofa.","Auf dem Tisch.","Im Schrank."],"correct":0,"why":"„Debajo del sofá.“"},{"q":"Was soll Diego danach tun?","choices":["Den Tisch decken.","Kochen.","Den Müll rausbringen."],"correct":2,"why":"Marta bittet: „¿Puedes sacar la basura?“"}],"tips":[{"title":"Has mirado","body":"Wörtlich: „Du hast geschaut/nachgesehen.“ Natürlich als Frage: „Hast du nachgesehen?“ Has ist eine Form von haber, mirado das Partizip von mirar. Zusammen bilden sie das Perfekt."}]},{"id":"basis2-7","title":"¿Trabajas o estudias?","subtitle":"Basis 2 · Paket 7","required":7,"deck_id":"palabra-basis-2","description":"Arbeit und Studium unterscheiden.","lines":[["Ana","¿Trabajas o estudias, Marcos?","Arbeitest oder studierst du, Marcos?"],["Marcos","Estudio en la universidad y también trabajo en una tienda.","Ich studiere an der Universität und arbeite auch in einem Geschäft."],["Ana","¡Qué bien! ¿Qué estudias?","Wie schön! Was studierst du?"],["Marcos","Estudio idiomas. Me gusta aprender español.","Ich studiere Sprachen. Ich lerne gerne Spanisch."],["Ana","¿Y tienes muchos exámenes?","Und hast du viele Prüfungen?"],["Marcos","Sí, tengo un examen el viernes. Mi profesora explica muy bien, pero tengo que estudiar mucho.","Ja, ich habe am Freitag eine Prüfung. Meine Professorin erklärt sehr gut, aber ich muss viel lernen."],["Ana","¡Mucha suerte!","Viel Glück!"]],"questions":[{"q":"Wo arbeitet Marcos?","choices":["Im Krankenhaus.","In einem Geschäft.","Im Restaurant."],"correct":1,"why":"„Trabajo en una tienda.“"},{"q":"Was studiert er?","choices":["Sprachen.","Sport.","Medizin."],"correct":0,"why":"„Estudio idiomas.“"},{"q":"Warum muss Marcos viel lernen?","choices":["Er schreibt am Freitag eine Prüfung.","Er zieht um.","Er reist am Wochenende."],"correct":0,"why":"„Tengo un examen el viernes.“"}],"tips":[{"title":"Estudiar","body":"Wörtlich/Grundbedeutung: „studieren“ oder „lernen“. Natürlich: Estudio idiomas = „Ich studiere Sprachen“; Tengo que estudiar = „Ich muss lernen“. Dasselbe spanische Verb deckt beides ab."}]},{"id":"basis2-8","title":"Un proyecto importante","subtitle":"Basis 2 · Paket 8","required":8,"deck_id":"palabra-basis-2","description":"Eine Aufgabe gemeinsam lösen.","lines":[["Laura","Buenos días, David. ¿Está listo el proyecto?","Guten Morgen, David. Ist das Projekt fertig?"],["David","Casi, pero tengo un problema. Me falta una parte.","Fast, aber ich habe ein Problem. Mir fehlt ein Teil."],["Laura","¿Es difícil?","Ist es schwierig?"],["David","Un poco. Y tenemos que ⟦entregarlo⟧ mañana.","Ein bisschen. Und wir müssen es morgen abgeben."],["Laura","Puedo ayudarte después de la reunión.","Ich kann dir nach der Besprechung helfen."],["David","¡Muchas gracias! ¿A qué hora termina?","Vielen Dank! Wann endet sie?"],["Laura","A las cuatro. Después tenemos tiempo para preparar la última parte.","Um vier. Danach haben wir Zeit, den letzten Teil vorzubereiten."],["David","Perfecto. Estoy de acuerdo.","Perfekt. Ich bin einverstanden."]],"questions":[{"q":"Was fehlt David noch?","choices":["Ein Teil des Projekts.","Sein Schlüssel.","Ein Zugticket."],"correct":0,"why":"„Me falta una parte.“"},{"q":"Bis wann muss das Projekt abgegeben werden?","choices":["Heute.","Morgen.","Am Sonntag."],"correct":1,"why":"„Tenemos que entregarlo mañana.“"},{"q":"Wann kann Laura helfen?","choices":["Vor der Besprechung.","Um sieben morgens.","Nach der Besprechung um vier."],"correct":2,"why":"Sie hilft nach der Besprechung, die um vier endet."}],"tips":[{"title":"Entregarlo","body":"Wörtlich: „es abgeben“ (entregar = abgeben, lo = es). Natürlich im Satz: Tenemos que entregarlo = „Wir müssen es abgeben“. Bei einem Infinitiv darf das Pronomen direkt hinten angehängt werden."}]},{"id":"basis2-9","title":"Vamos a cocinar","subtitle":"Basis 2 · Paket 9","required":9,"deck_id":"palabra-basis-2","description":"Ein Rezept Schritt für Schritt verstehen.","lines":[["Marta","¿Qué vamos a cocinar esta noche?","Was wollen wir heute Abend kochen?"],["Diego","¿Una sopa de verduras?","Eine Gemüsesuppe?"],["Marta","¡Perfecto! Tenemos patatas, tomates y cebollas.","Perfekt! Wir haben Kartoffeln, Tomaten und Zwiebeln."],["Diego","¿Y qué necesitamos hacer primero?","Und was müssen wir zuerst machen?"],["Marta","Primero cortamos las verduras. Después añadimos agua y un poco de sal.","Zuerst schneiden wir das Gemüse. Danach geben wir Wasser und etwas Salz hinzu."],["Diego","¿Y luego?","Und danach?"],["Marta","⟦Dejamos hervir⟧ la sopa.","Wir lassen die Suppe kochen."],["Diego","¡Muy bien! Yo preparo la mesa.","Sehr gut! Ich decke den Tisch."]],"questions":[{"q":"Was kochen die beiden?","choices":["Reis mit Fisch.","Gemüsesuppe.","Ein Bocadillo."],"correct":1,"why":"„Una sopa de verduras.“"},{"q":"Was passiert zuerst?","choices":["Das Gemüse wird geschnitten.","Die Suppe wird serviert.","Die Küche wird geputzt."],"correct":0,"why":"„Primero cortamos las verduras.“"},{"q":"Was macht Diego währenddessen?","choices":["Er geht einkaufen.","Er bringt den Müll raus.","Er deckt den Tisch."],"correct":2,"why":"„Yo preparo la mesa.“"}],"tips":[{"title":"Dejamos hervir","body":"Wörtlich: „Wir lassen [es] kochen/sieden.“ Natürlich in einem Rezept: „Wir lassen es köcheln/kochen.“ Dejar + Infinitiv heißt, dass man etwas geschehen lässt."}]},{"id":"basis2-10","title":"Una cena con amigos","subtitle":"Basis 2 · Paket 10","required":10,"deck_id":"palabra-basis-2","description":"Vorlieben beim Abendessen verstehen.","lines":[["Lucía","¡⟦Qué bien huele⟧! Tengo mucha hambre.","Wie gut das riecht! Ich habe großen Hunger."],["Carlos","He preparado una sopa de verduras y un poco de arroz.","Ich habe eine Gemüsesuppe und etwas Reis zubereitet."],["Lucía","¡Qué rico! ¿La sopa es picante?","Wie lecker! Ist die Suppe scharf?"],["Carlos","No, es suave. Pero puedes añadir pimienta.","Nein, sie ist mild. Aber du kannst Pfeffer dazugeben."],["Lucía","Perfecto. ¿Y el arroz tiene carne?","Perfekt. Und ist im Reis Fleisch?"],["Carlos","No, es vegetariano.","Nein, er ist vegetarisch."],["Lucía","¡Estupendo! Mi amiga Elena no come carne.","Super! Meine Freundin Elena isst kein Fleisch."],["Carlos","Entonces también puede comer con nosotros. ¡Buen provecho!","Dann kann sie auch mit uns essen. Guten Appetit!"],["Lucía","Gracias. ¡Está delicioso!","Danke. Es ist köstlich!"]],"questions":[{"q":"Was hat Carlos zubereitet?","choices":["Suppe und Reis.","Fisch und Salat.","Toast und Kaffee."],"correct":0,"why":"„Una sopa de verduras y un poco de arroz.“"},{"q":"Wie schmeckt die Suppe?","choices":["Sehr scharf.","Mild.","Bitter."],"correct":1,"why":"„No, es suave.“"},{"q":"Warum kann Elena mitessen?","choices":["Sie hat keinen Hunger.","Sie mag nur Süßes.","Das Essen enthält kein Fleisch."],"correct":2,"why":"„Es vegetariano“ und „Elena no come carne“."}],"tips":[{"title":"Qué bien huele","body":"Wörtlich ungefähr: „Wie gut [es] riecht!“ Natürlich: „Das riecht aber gut!“ Qué verstärkt hier den Ausruf, und das „es“ wird im Spanischen nicht eigens ausgesprochen."}]},{"id":"basis3-1","title":"Una mesa para dos","subtitle":"Basis 3 · Paket 1","deck_id":"palabra-basis-3","required":1,"description":"Im Restaurant bestellen.","lines":[["Camarera","Buenas noches. ¿Tenéis una reserva?","Guten Abend. Habt ihr reserviert?"],["Lucía","No. ¿Hay una mesa para dos disponible?","Nein. Ist ein Tisch für zwei frei?"],["Camarera","Sí, claro. Por aquí, por favor.","Ja, natürlich. Hier entlang, bitte."],["Carlos","Gracias. ¿Qué recomienda hoy?","Danke. Was empfehlen Sie heute?"],["Camarera","El menú del día está muy bien. De primero hay sopa y de segundo pescado con patatas.","Das Tagesmenü ist sehr gut. Als Vorspeise gibt es Suppe und als Hauptgericht Fisch mit Kartoffeln."],["Lucía","Perfecto. Para mí, la sopa y el pescado.","Perfekt. Für mich die Suppe und den Fisch."],["Carlos","Yo querría una ensalada y después pollo, por favor.","Ich hätte gern einen Salat und danach Hähnchen, bitte."],["Camarera","Muy bien. ¿Algo de beber?","Sehr gut. Etwas zu trinken?"],["Carlos","Agua para los dos, gracias.","Wasser für uns beide, danke."]],"questions":[{"q":"Haben die beiden reserviert?","choices":["Nein, sie haben keine Reservierung.","Ja, für vier Personen.","Ja, für morgen."],"correct":0,"why":"Im Dialog steht: Nein, sie haben keine Reservierung.."},{"q":"Was empfiehlt die Kellnerin?","choices":["Nur Brot und Käse.","Das Tagesmenü mit Suppe und Fisch.","Ein Frühstück."],"correct":1,"why":"Im Dialog steht: Das Tagesmenü mit Suppe und Fisch.."},{"q":"Was bestellt Lucía?","choices":["Salat und Hähnchen.","Nur Wasser.","Suppe und Fisch."],"correct":2,"why":"Im Dialog steht: Suppe und Fisch.."}],"tips":[{"title":"¿Tenéis una reserva?","body":"Wörtlich: „Habt ihr eine Reservierung?“ Natürlich: „Habt ihr reserviert?“ Tenéis ist die vosotros-Form von tener – in Spanien sehr alltäglich."}]},{"id":"basis3-2","title":"Falta un plato","subtitle":"Basis 3 · Paket 2","deck_id":"palabra-basis-3","required":2,"description":"Eine fehlende Bestellung reklamieren.","lines":[["Carlos","Disculpe, creo que falta algo. Hemos pedido dos platos, pero solo tenemos uno.","Entschuldigen Sie, ich glaube, etwas fehlt. Wir haben zwei Gerichte bestellt, aber nur eines bekommen."],["Camarero","Tiene razón. Lo siento mucho. ¿Qué plato falta?","Sie haben recht. Das tut mir sehr leid. Welches Gericht fehlt?"],["Carlos","El pescado con patatas.","Der Fisch mit Kartoffeln."],["Camarero","Ahora mismo lo traigo. No va a tardar mucho.","Ich bringe ihn sofort. Es dauert nicht lange."],["Lucía","Gracias. ¿Y el pan está incluido?","Danke. Und ist das Brot inbegriffen?"],["Camarero","Sí, está incluido en el menú.","Ja, es ist im Menü enthalten."],["Carlos","¡Estaba buenísimo! ¿Podemos pagar por separado?","Es war unglaublich lecker! Können wir getrennt bezahlen?"],["Camarero","Por supuesto. ¿Quieren el recibo?","Selbstverständlich. Möchten Sie den Beleg?"]],"questions":[{"q":"Welches Gericht fehlt?","choices":["Die Suppe.","Fisch mit Kartoffeln.","Das Brot."],"correct":1,"why":"Im Dialog steht: Fisch mit Kartoffeln.."},{"q":"Ist das Brot im Menü enthalten?","choices":["Nein, es kostet extra.","Das wird nicht geklärt.","Ja, es ist enthalten."],"correct":2,"why":"Im Dialog steht: Ja, es ist enthalten.."},{"q":"Wie möchten sie bezahlen?","choices":["Getrennt.","Nur bar.","Morgen."],"correct":0,"why":"Im Dialog steht: Getrennt.."}],"tips":[{"title":"Hemos pedido","body":"Wörtlich: „Wir haben bestellt.“ Natürlich: „Wir haben bestellt.“ Mit hemos + Partizip bildet Spanisch das Pretérito Perfecto."}]},{"id":"basis3-3","title":"Un billete a Valencia","subtitle":"Basis 3 · Paket 3","deck_id":"palabra-basis-3","required":3,"description":"Ein Zugticket kaufen.","lines":[["Viajera","Buenos días. Querría un billete a Valencia.","Guten Morgen. Ich hätte gerne eine Fahrkarte nach Valencia."],["Empleado","¿De ida o de ida y vuelta?","Einfach oder hin und zurück?"],["Viajera","De ida y vuelta, por favor. Voy hoy y vuelvo el domingo.","Hin und zurück, bitte. Ich fahre heute und komme Sonntag zurück."],["Empleado","Hay un tren directo a las diez.","Um zehn gibt es einen direkten Zug."],["Viajera","Perfecto. ¿De qué andén sale?","Perfekt. Von welchem Bahnsteig fährt er ab?"],["Empleado","Del andén cuatro. Pero el tren lleva diez minutos de retraso.","Von Bahnsteig vier. Aber der Zug hat zehn Minuten Verspätung."],["Viajera","No pasa nada. ¿Tengo que hacer transbordo?","Das macht nichts. Muss ich umsteigen?"],["Empleado","No, es directo.","Nein, er fährt direkt."]],"questions":[{"q":"Welche Fahrkarte kauft die Reisende?","choices":["Nur Hinfahrt.","Eine Monatskarte.","Hin- und Rückfahrt."],"correct":2,"why":"Im Dialog steht: Hin- und Rückfahrt.."},{"q":"Wann kommt sie zurück?","choices":["Am Sonntag.","Am Freitag.","Am Montag."],"correct":0,"why":"Im Dialog steht: Am Sonntag.."},{"q":"Muss sie umsteigen?","choices":["Ja, zweimal.","Nein, es ist eine Direktverbindung.","Ja, einmal."],"correct":1,"why":"Im Dialog steht: Nein, es ist eine Direktverbindung.."}],"tips":[{"title":"De ida y vuelta","body":"Wörtlich: „Von Hinfahrt und Rückfahrt.“ Natürlich: „Hin und zurück.“ Ida heißt Hinfahrt; vuelta heißt Rückkehr oder Rückfahrt."}]},{"id":"basis3-4","title":"Perdidos en Madrid","subtitle":"Basis 3 · Paket 4","deck_id":"palabra-basis-3","required":4,"description":"Mit öffentlichen Verkehrsmitteln ans Ziel.","lines":[["Ana","Creo que nos hemos perdido. ¿Tienes el mapa?","Ich glaube, wir haben uns verlaufen. Hast du den Stadtplan?"],["Pablo","Sí, pero no entiendo dónde estamos.","Ja, aber ich verstehe nicht, wo wir sind."],["Ana","Tenemos que llegar al aeropuerto. ¿Vamos en taxi o en metro?","Wir müssen zum Flughafen. Nehmen wir ein Taxi oder die U-Bahn?"],["Pablo","Mejor en metro. Es más barato.","Lieber die U-Bahn. Sie ist günstiger."],["Ana","¿Qué línea necesitamos?","Welche Linie brauchen wir?"],["Pablo","La línea ocho. Tenemos que subir aquí y bajar en la última parada.","Linie acht. Wir müssen hier einsteigen und an der letzten Haltestelle aussteigen."],["Ana","Perfecto. ¿Y nuestras maletas?","Perfekt. Und unsere Koffer?"],["Pablo","¡Están aquí! No te preocupes.","Sie sind hier! Mach dir keine Sorgen."]],"questions":[{"q":"Wohin müssen sie gelangen?","choices":["Zum Flughafen.","Zum Strand.","Zum Hotel."],"correct":0,"why":"Im Dialog steht: Zum Flughafen.."},{"q":"Welches Verkehrsmittel wählen sie?","choices":["Ein Taxi.","Die U-Bahn.","Das Fahrrad."],"correct":1,"why":"Im Dialog steht: Die U-Bahn.."},{"q":"Wo müssen sie aussteigen?","choices":["An der ersten Haltestelle.","Am Bahnhof.","An der letzten Haltestelle."],"correct":2,"why":"Im Dialog steht: An der letzten Haltestelle.."}],"tips":[{"title":"Nos hemos perdido","body":"Wörtlich: „Wir haben uns verloren.“ Natürlich: „Wir haben uns verlaufen.“ Perderse ist reflexiv – mit nos beschreibt Pablo und Ana, dass sie selbst die Orientierung verloren haben."}]},{"id":"basis3-5","title":"Una habitación doble","subtitle":"Basis 3 · Paket 5","deck_id":"palabra-basis-3","required":5,"description":"Im Hotel einchecken.","lines":[["Recepcionista","Buenas tardes. Bienvenidos al hotel.","Guten Tag. Willkommen im Hotel."],["Elena","Hola. Tenemos una reserva a nombre de Elena Ruiz.","Hallo. Wir haben eine Reservierung auf den Namen Elena Ruiz."],["Recepcionista","Un momento… Sí, una habitación doble para tres noches.","Einen Moment ... Ja, ein Doppelzimmer für drei Nächte."],["Elena","Exacto. ¿Está incluido el desayuno?","Genau. Ist das Frühstück inbegriffen?"],["Recepcionista","Sí. Se sirve de siete a diez.","Ja. Es wird von sieben bis zehn serviert."],["Elena","Perfecto. ¿En qué planta está nuestra habitación?","Perfekt. In welchem Stock liegt unser Zimmer?"],["Recepcionista","En la tercera. Pueden subir en ascensor.","Im dritten. Sie können den Aufzug nehmen."],["Elena","Muchas gracias. ¿A qué hora es la salida el domingo?","Vielen Dank. Um wie viel Uhr müssen wir am Sonntag auschecken?"],["Recepcionista","Antes de las once.","Vor elf Uhr."]],"questions":[{"q":"Wie viele Nächte bleiben die Gäste?","choices":["Zwei Nächte.","Drei Nächte.","Fünf Nächte."],"correct":1,"why":"Im Dialog steht: Drei Nächte.."},{"q":"Ist das Frühstück inbegriffen?","choices":["Nein.","Nur am Sonntag.","Ja, von sieben bis zehn."],"correct":2,"why":"Im Dialog steht: Ja, von sieben bis zehn.."},{"q":"Wann müssen sie auschecken?","choices":["Vor elf Uhr.","Um sieben Uhr.","Nachmittags um drei."],"correct":0,"why":"Im Dialog steht: Vor elf Uhr.."}],"tips":[{"title":"A nombre de","body":"Wörtlich: „Auf den Namen von …“ Natürlich: „Auf den Namen …“ Eine feste Formulierung für Reservierungen und Buchungen."}]},{"id":"basis3-6","title":"El aire acondicionado no funciona","subtitle":"Basis 3 · Paket 6","deck_id":"palabra-basis-3","required":6,"description":"Hotelprobleme erklären und lösen.","lines":[["Huésped","Buenas noches. Tenemos un problema con la habitación.","Guten Abend. Wir haben ein Problem mit dem Zimmer."],["Recepcionista","Dígame, ¿qué ocurre?","Sagen Sie, was ist los?"],["Huésped","El aire acondicionado no funciona y hace mucho calor.","Die Klimaanlage funktioniert nicht und es ist sehr heiß."],["Recepcionista","Lo siento. Voy a avisar a un compañero para que lo arregle.","Das tut mir leid. Ich sage einem Kollegen Bescheid, damit er sie repariert."],["Huésped","Gracias. Además, hay mucho ruido en el pasillo.","Danke. Außerdem ist es im Flur sehr laut."],["Recepcionista","Entiendo. También podemos ofrecerles otra habitación más tranquila.","Verstehe. Wir können Ihnen auch ein ruhigeres Zimmer anbieten."],["Huésped","Preferimos cambiar de habitación, si es posible.","Wir würden lieber das Zimmer wechseln, wenn möglich."],["Recepcionista","Por supuesto. Lo preparamos lo antes posible.","Natürlich. Wir bereiten es schnellstmöglich vor."]],"questions":[{"q":"Welche Probleme gibt es?","choices":["Kein Frühstück und wenig Platz.","Eine verschlossene Rezeption.","Kaputte Klimaanlage und Lärm."],"correct":2,"why":"Im Dialog steht: Kaputte Klimaanlage und Lärm.."},{"q":"Welche Lösung wird angeboten?","choices":["Ein anderes, ruhigeres Zimmer.","Ein kostenloses Taxi.","Ein Abendessen."],"correct":0,"why":"Im Dialog steht: Ein anderes, ruhigeres Zimmer.."},{"q":"Wofür entscheiden sich die Gäste?","choices":["Für eine Abreise.","Für einen Zimmerwechsel.","Für ein Taxi."],"correct":1,"why":"Im Dialog steht: Für einen Zimmerwechsel.."}],"tips":[{"title":"Hace mucho calor","body":"Wörtlich: „Es macht viel Wärme.“ Natürlich: „Es ist sehr heiß.“ Bei Wetter und Temperaturen verwendet Spanisch oft hacer, wo Deutsch sein verwendet."}]},{"id":"basis3-7","title":"Buscando una chaqueta","subtitle":"Basis 3 · Paket 7","deck_id":"palabra-basis-3","required":7,"description":"Kleidung und Farben auswählen.","lines":[["Dependienta","Hola, ¿puedo ayudarte?","Hallo, kann ich dir helfen?"],["Lucía","Sí, busco una chaqueta para el otoño.","Ja, ich suche eine Jacke für den Herbst."],["Dependienta","¿Qué talla necesitas?","Welche Größe brauchst du?"],["Lucía","La mediana. ¿Tenéis esta chaqueta en azul?","Mittel. Habt ihr diese Jacke in Blau?"],["Dependienta","Sí, también la tenemos en negro y verde.","Ja, wir haben sie auch in Schwarz und Grün."],["Lucía","Prefiero la azul. ¿Puedo probármela?","Ich hätte lieber die blaue. Kann ich sie anprobieren?"],["Dependienta","Claro. Los probadores están al fondo.","Klar. Die Umkleidekabinen sind hinten."],["Lucía","Gracias. ¡Ahora vuelvo!","Danke. Ich komme gleich wieder!"]],"questions":[{"q":"Was sucht Lucía?","choices":["Eine Jacke für den Herbst.","Ein Kleid für den Sommer.","Neue Schuhe."],"correct":0,"why":"Im Dialog steht: Eine Jacke für den Herbst.."},{"q":"Welche Farbe bevorzugt sie?","choices":["Grün.","Blau.","Schwarz."],"correct":1,"why":"Im Dialog steht: Blau.."},{"q":"Was möchte sie vor dem Kauf tun?","choices":["Ein Foto machen.","Die Verkäuferin anrufen.","Die Jacke anprobieren."],"correct":2,"why":"Im Dialog steht: Die Jacke anprobieren.."}],"tips":[{"title":"Probármela","body":"Wörtlich: „Sie mir anprobieren.“ Natürlich: „Sie anprobieren.“ Me bedeutet hier „mir“, la steht für die Jacke. Beide Pronomen können direkt am Infinitiv hängen."}]},{"id":"basis3-8","title":"Me queda demasiado grande","subtitle":"Basis 3 · Paket 8","deck_id":"palabra-basis-3","required":8,"description":"Größe und Rabatt beim Kleidungskauf.","lines":[["Lucía","Disculpa, me he probado esta chaqueta, pero me queda demasiado grande.","Entschuldigung, ich habe diese Jacke anprobiert, aber sie ist mir viel zu groß."],["Dependienta","¿Quieres una talla menos?","Möchtest du eine Größe kleiner?"],["Lucía","Sí, por favor. Y si puede ser, en negro.","Ja, bitte. Und wenn möglich in Schwarz."],["Dependienta","Aquí tienes. Esta está rebajada.","Hier, bitte. Diese ist reduziert."],["Lucía","¡Qué bien! ¿Cuánto descuento tiene?","Wie schön! Wie hoch ist der Rabatt?"],["Dependienta","Un veinte por ciento.","Zwanzig Prozent."],["Lucía","Esta me queda mucho mejor. Me la quedo.","Diese passt mir viel besser. Ich nehme sie."],["Dependienta","Perfecto. Guarda el recibo por si necesitas devolverla.","Perfekt. Heb den Beleg auf, falls du sie zurückgeben möchtest."]],"questions":[{"q":"Warum passt die erste Jacke nicht?","choices":["Sie ist zu klein.","Sie ist viel zu groß.","Sie ist kaputt."],"correct":1,"why":"Im Dialog steht: Sie ist viel zu groß.."},{"q":"Wie hoch ist der Rabatt?","choices":["Zehn Prozent.","Fünfzig Prozent.","Zwanzig Prozent."],"correct":2,"why":"Im Dialog steht: Zwanzig Prozent.."},{"q":"Warum soll Lucía den Beleg behalten?","choices":["Für eine mögliche Rückgabe.","Für einen Gutschein.","Um die Größe zu merken."],"correct":0,"why":"Im Dialog steht: Für eine mögliche Rückgabe.."}],"tips":[{"title":"Me queda grande","body":"Wörtlich: „Sie bleibt mir groß.“ Natürlich: „Sie ist mir zu groß.“ Quedar beschreibt bei Kleidung, wie etwas an einer Person sitzt."}]},{"id":"basis3-9","title":"He perdido mi cartera","subtitle":"Basis 3 · Paket 9","deck_id":"palabra-basis-3","required":9,"description":"Eine verlorene Geldbörse melden.","lines":[["Turista","Disculpe, ¿me puede ayudar?","Entschuldigen Sie, können Sie mir helfen?"],["Empleado","Claro. ¿Qué ha pasado?","Natürlich. Was ist passiert?"],["Turista","Creo que he perdido mi cartera en el autobús.","Ich glaube, ich habe meine Geldbörse im Bus verloren."],["Empleado","¿Recuerda qué línea ha tomado?","Wissen Sie noch, welche Linie Sie genommen haben?"],["Turista","La línea cinco. He bajado hace diez minutos.","Linie fünf. Ich bin vor zehn Minuten ausgestiegen."],["Empleado","Vamos a llamar a la empresa de autobuses.","Wir rufen das Busunternehmen an."],["Turista","Muchas gracias. También tengo mi documento de identidad en la cartera.","Vielen Dank. Mein Ausweis ist auch in der Geldbörse."],["Empleado","Entiendo. Si no aparece, puede ir a la comisaría.","Verstehe. Falls sie nicht auftaucht, können Sie zur Polizeiwache gehen."]],"questions":[{"q":"Was wurde verloren?","choices":["Ein Koffer.","Das Handy.","Die Geldbörse."],"correct":2,"why":"Im Dialog steht: Die Geldbörse.."},{"q":"Wo wurde sie vermutlich verloren?","choices":["Im Bus.","Im Hotel.","Im Restaurant."],"correct":0,"why":"Im Dialog steht: Im Bus.."},{"q":"Was schlägt der Angestellte zuerst vor?","choices":["Eine neue Fahrkarte kaufen.","Das Busunternehmen anrufen.","Zum Flughafen fahren."],"correct":1,"why":"Im Dialog steht: Das Busunternehmen anrufen.."}],"tips":[{"title":"He perdido mi cartera","body":"Wörtlich: „Ich habe meine Geldbörse verloren.“ Natürlich: „Ich habe meine Geldbörse verloren.“ Das Perfekt wird mit der Form von haber (he) und einem Partizip (perdido) gebildet."}]},{"id":"basis3-10","title":"Una solución por fin","subtitle":"Basis 3 · Paket 10","deck_id":"palabra-basis-3","required":10,"description":"Ein Problem erfolgreich klären.","lines":[["Empleado","Buenas tardes. Tenemos buenas noticias sobre su cartera.","Guten Tag. Wir haben gute Neuigkeiten zu Ihrer Geldbörse."],["Turista","¿De verdad? ¡Qué alegría!","Wirklich? Was für eine Freude!"],["Empleado","Un conductor la ha encontrado en el autobús.","Ein Fahrer hat sie im Bus gefunden."],["Turista","¡Por suerte! ¿Dónde puedo recogerla?","Zum Glück! Wo kann ich sie abholen?"],["Empleado","En nuestra oficina, cerca de la estación.","In unserem Büro in der Nähe des Bahnhofs."],["Turista","Perdón, ¿puede repetirlo más despacio?","Entschuldigung, können Sie das langsamer wiederholen?"],["Empleado","Claro. Tiene que ir a la oficina de transporte, al lado de la estación.","Natürlich. Sie müssen zum Verkehrsbüro neben dem Bahnhof gehen."],["Turista","Ahora entiendo. Muchas gracias por su ayuda.","Jetzt verstehe ich. Vielen Dank für Ihre Hilfe."],["Empleado","De nada. ¡Que tenga un buen día!","Gern geschehen. Einen schönen Tag noch!"]],"questions":[{"q":"Wer hat die Geldbörse gefunden?","choices":["Ein Busfahrer.","Ein Hotelgast.","Eine Kellnerin."],"correct":0,"why":"Im Dialog steht: Ein Busfahrer.."},{"q":"Wo kann sie abgeholt werden?","choices":["In der Schule.","Im Büro neben dem Bahnhof.","Am Flughafen."],"correct":1,"why":"Im Dialog steht: Im Büro neben dem Bahnhof.."},{"q":"Warum bittet die Person um Wiederholung?","choices":["Sie möchte die Rechnung bezahlen.","Sie hat den Namen vergessen.","Sie hat die Wegbeschreibung nicht verstanden."],"correct":2,"why":"Im Dialog steht: Sie hat die Wegbeschreibung nicht verstanden.."}],"tips":[{"title":"¡Que tenga un buen día!","body":"Wörtlich: „Dass Sie einen guten Tag haben!“ Natürlich: „Einen schönen Tag noch!“ Que + Subjuntivo kann einen Wunsch ausdrücken, hier höflich mit tenga."}]},{"id":"basis4-1","title":"¿Qué hiciste ayer?","subtitle":"Basis 4 · Paket 1","deck_id":"palabra-basis-4","required":1,"description":"Über einen Ausflug erzählen.","lines":[["Lucía","¡Hola, Marcos! ¿Qué hiciste ayer?","Hallo Marcos! Was hast du gestern gemacht?"],["Marcos","Fui a un concierto con unos amigos.","Ich war mit ein paar Freunden auf einem Konzert."],["Lucía","¡Qué bien! ¿Te divertiste?","Wie schön! Hattest du Spaß?"],["Marcos","Muchísimo. Conocí a una chica muy simpática y hablamos durante horas.","Sehr viel. Ich lernte ein sehr nettes Mädchen kennen und wir redeten stundenlang."],["Lucía","¿Y qué música escuchasteis?","Und welche Musik habt ihr gehört?"],["Marcos","Música latinoamericana. ¡Me encantó!","Lateinamerikanische Musik. Es hat mir total gefallen!"],["Lucía","¿Vas a volver a verla?","Wirst du sie wiedersehen?"],["Marcos","Eso espero. Quedamos para tomar un café el sábado.","Das hoffe ich. Wir haben uns für Samstag zum Kaffeetrinken verabredet."]],"questions":[{"q":"Wohin ging Marcos gestern?","choices":["Ins Kino.","Auf ein Konzert.","Zum Bahnhof."],"correct":1,"why":"Im Dialog steht: Auf ein Konzert.."},{"q":"Wen lernte er kennen?","choices":["Einen Kollegen.","Seine Lehrerin.","Ein nettes Mädchen."],"correct":2,"why":"Im Dialog steht: Ein nettes Mädchen.."},{"q":"Was ist für Samstag geplant?","choices":["Ein Treffen im Café.","Ein Fußballspiel.","Eine Prüfung."],"correct":0,"why":"Im Dialog steht: Ein Treffen im Café.."}],"tips":[{"title":"¿Qué hiciste?","body":"Wörtlich: „Was machtest du?“ Natürlich: „Was hast du gemacht?“ Spanisch verwendet hier das Indefinido; im deutschen Gespräch ist oft das Perfekt üblicher."}]},{"id":"basis4-2","title":"Cuando éramos pequeños","subtitle":"Basis 4 · Paket 2","deck_id":"palabra-basis-4","required":2,"description":"Kindheit und Erinnerungen.","lines":[["Ana","¿Dónde vivías cuando eras pequeño?","Wo hast du gewohnt, als du klein warst?"],["Pablo","Vivía en un pueblo cerca del mar.","Ich wohnte in einem Dorf am Meer."],["Ana","¡Qué bonito! ¿Qué hacías allí?","Wie schön! Was hast du dort gemacht?"],["Pablo","Todos los veranos jugaba al fútbol con mis amigos. También solíamos ir a la playa.","Jeden Sommer spielte ich Fußball mit meinen Freunden. Außerdem gingen wir gewöhnlich zum Strand."],["Ana","¿Echas de menos esa época?","Vermisst du diese Zeit?"],["Pablo","Sí, mucho. Pero ahora me gusta vivir en la ciudad.","Ja, sehr. Aber jetzt wohne ich gern in der Stadt."],["Ana","¿Tus padres siguen viviendo en el pueblo?","Wohnen deine Eltern immer noch in dem Dorf?"],["Pablo","Sí, y los visito de vez en cuando.","Ja, und ich besuche sie ab und zu."]],"questions":[{"q":"Wo wuchs Pablo auf?","choices":["In einer großen Stadt.","In den Bergen.","In einem Dorf am Meer."],"correct":2,"why":"Im Dialog steht: In einem Dorf am Meer.."},{"q":"Was machte er jeden Sommer?","choices":["Er spielte Fußball.","Er ging zur Universität.","Er arbeitete im Hotel."],"correct":0,"why":"Im Dialog steht: Er spielte Fußball.."},{"q":"Wo wohnen seine Eltern heute?","choices":["In Berlin.","Noch immer im Dorf.","In der Stadt bei Pablo."],"correct":1,"why":"Im Dialog steht: Noch immer im Dorf.."}],"tips":[{"title":"Solíamos ir","body":"Wörtlich: „Wir pflegten zu gehen.“ Natürlich: „Wir gingen früher gewöhnlich.“ Soler + Infinitiv beschreibt eine regelmäßige Gewohnheit."}]},{"id":"basis4-3","title":"Estoy un poco nerviosa","subtitle":"Basis 4 · Paket 3","deck_id":"palabra-basis-4","required":3,"description":"Nervosität vor einem Termin verstehen.","lines":[["Elena","Mañana tengo una entrevista de trabajo y estoy muy nerviosa.","Morgen habe ich ein Bewerbungsgespräch und bin sehr nervös."],["Lucía","Es normal. ¿Por qué estás tan preocupada?","Das ist normal. Warum bist du so besorgt?"],["Elena","Tengo miedo de no saber responder a las preguntas.","Ich habe Angst, die Fragen nicht beantworten zu können."],["Lucía","Pero estás muy bien preparada. ¡Deberías estar orgullosa!","Aber du bist sehr gut vorbereitet. Du solltest stolz sein!"],["Elena","Gracias. Ahora me siento un poco mejor.","Danke. Jetzt fühle ich mich etwas besser."],["Lucía","Seguro que todo va bien. ¡Mucha suerte!","Bestimmt wird alles gut. Viel Glück!"]],"questions":[{"q":"Warum ist Elena nervös?","choices":["Sie hat morgen ein Bewerbungsgespräch.","Sie muss verreisen.","Sie hat ihre Schlüssel verloren."],"correct":0,"why":"Im Dialog steht: Sie hat morgen ein Bewerbungsgespräch.."},{"q":"Wovor hat sie Angst?","choices":["Dass der Bus zu früh kommt.","Dass sie die Fragen nicht beantworten kann.","Dass es regnet."],"correct":1,"why":"Im Dialog steht: Dass sie die Fragen nicht beantworten kann.."},{"q":"Wie hilft Lucía?","choices":["Sie storniert den Termin.","Sie kauft ihr ein Ticket.","Sie macht Elena Mut."],"correct":2,"why":"Im Dialog steht: Sie macht Elena Mut.."}],"tips":[{"title":"Me siento mejor","body":"Wörtlich: „Ich fühle mich besser.“ Natürlich: „Mir geht es besser.“ Sentirse heißt sich fühlen; sentarse heißt dagegen sich hinsetzen."}]},{"id":"basis4-4","title":"No tengo ganas de salir","subtitle":"Basis 4 · Paket 4","deck_id":"palabra-basis-4","required":4,"description":"Für einen Freund da sein.","lines":[["Pablo","¿Qué te pasa, Ana? Estás muy callada.","Was ist los, Ana? Du bist sehr still."],["Ana","Estoy bajo mucha presión en el trabajo. No tengo ganas de salir esta noche.","Ich stehe bei der Arbeit sehr unter Druck. Ich habe heute Abend keine Lust auszugehen."],["Pablo","Lo entiendo. ¿Quieres hablar de ello?","Das verstehe ich. Möchtest du darüber reden?"],["Ana","Sí, gracias. Últimamente tengo mucho estrés.","Ja, danke. In letzter Zeit habe ich viel Stress."],["Pablo","Entonces podemos quedarnos en casa y ver una película.","Dann können wir zu Hause bleiben und einen Film ansehen."],["Ana","Eso me apetece más. Gracias por escucharme.","Darauf habe ich eher Lust. Danke, dass du mir zuhörst."],["Pablo","Para eso están los amigos. ¡Ánimo!","Dafür sind Freunde da. Kopf hoch!"]],"questions":[{"q":"Warum möchte Ana nicht ausgehen?","choices":["Sie hat kein Geld.","Sie steht bei der Arbeit unter Druck.","Sie wartet auf den Zug."],"correct":1,"why":"Im Dialog steht: Sie steht bei der Arbeit unter Druck.."},{"q":"Was schlägt Pablo vor?","choices":["Ins Restaurant gehen.","Ein Konzert besuchen.","Zuhause einen Film ansehen."],"correct":2,"why":"Im Dialog steht: Zuhause einen Film ansehen.."},{"q":"Wie reagiert Ana?","choices":["Sie findet den Vorschlag gut.","Sie sagt sofort ab.","Sie fährt allein weg."],"correct":0,"why":"Im Dialog steht: Sie findet den Vorschlag gut.."}],"tips":[{"title":"Tengo ganas de…","body":"Wörtlich: „Ich habe Verlangen danach, …“ Natürlich: „Ich habe Lust auf …“ Mit no davor wird die feste Wendung verneint: no tengo ganas de salir."}]},{"id":"basis4-5","title":"Mis planes para el futuro","subtitle":"Basis 4 · Paket 5","deck_id":"palabra-basis-4","required":5,"description":"Zukunftspläne besprechen.","lines":[["Marcos","¿Qué tienes pensado hacer el próximo año?","Was hast du nächstes Jahr vor?"],["Elena","Quiero viajar por Sudamérica y mejorar mi español.","Ich möchte durch Südamerika reisen und mein Spanisch verbessern."],["Marcos","¡Qué buena idea! ¿Ya estás ahorrando?","Was für eine gute Idee! Sparst du schon?"],["Elena","Sí, desde hace unos meses. Mi objetivo es viajar durante tres meses.","Ja, schon seit einigen Monaten. Mein Ziel ist, drei Monate lang zu reisen."],["Marcos","¿Y después?","Und danach?"],["Elena","Todavía no lo sé. Quizá busque un nuevo trabajo.","Das weiß ich noch nicht. Vielleicht suche ich einen neuen Job."],["Marcos","¡Seguro que será una experiencia increíble!","Das wird bestimmt eine unglaubliche Erfahrung!"]],"questions":[{"q":"Wohin möchte Elena reisen?","choices":["Nach Japan.","In die Schweiz.","Nach Südamerika."],"correct":2,"why":"Im Dialog steht: Nach Südamerika.."},{"q":"Wie lange möchte sie reisen?","choices":["Drei Monate.","Ein Jahr.","Drei Tage."],"correct":0,"why":"Im Dialog steht: Drei Monate.."},{"q":"Was könnte sie danach machen?","choices":["Ein Hotel kaufen.","Einen neuen Job suchen.","In die Schule gehen."],"correct":1,"why":"Im Dialog steht: Einen neuen Job suchen.."}],"tips":[{"title":"Tengo pensado viajar","body":"Wörtlich: „Ich habe Reisen gedacht/geplant.“ Natürlich: „Ich habe vor zu reisen.“ Tener pensado + Infinitiv beschreibt einen schon gefassten Plan."}]},{"id":"basis4-6","title":"¿Qué harías tú?","subtitle":"Basis 4 · Paket 6","deck_id":"palabra-basis-4","required":6,"description":"Entscheidungen und Möglichkeiten abwägen.","lines":[["Ana","Tengo dos ofertas de trabajo y no sé cuál elegir.","Ich habe zwei Jobangebote und weiß nicht, welches ich wählen soll."],["Pablo","¿Cuáles son las opciones?","Was sind die Optionen?"],["Ana","Una está cerca de casa, pero la otra ofrece más dinero.","Eines ist nah an meinem Zuhause, aber das andere bietet mehr Geld."],["Pablo","¿Y cuál te gustaría más?","Und welches würde dir besser gefallen?"],["Ana","Si tuviera más tiempo para decidir, sería más fácil.","Wenn ich mehr Zeit zum Entscheiden hätte, wäre es einfacher."],["Pablo","Yo consideraría también el horario y los compañeros.","Ich würde auch die Arbeitszeiten und Kollegen berücksichtigen."],["Ana","Tienes razón. No quiero elegir solo por el dinero.","Du hast recht. Ich möchte nicht nur wegen des Geldes entscheiden."],["Pablo","Entonces piensa en las ventajas y desventajas de cada trabajo.","Dann denke über die Vor- und Nachteile der beiden Jobs nach."]],"questions":[{"q":"Worüber muss Ana entscheiden?","choices":["Zwischen zwei Jobangeboten.","Über einen Umzug nach Spanien.","Über ein Auto."],"correct":0,"why":"Im Dialog steht: Zwischen zwei Jobangeboten.."},{"q":"Worin unterscheiden sich die Angebote?","choices":["Urlaub und Wetter.","Entfernung und Gehalt.","Nur die Kleidung."],"correct":1,"why":"Im Dialog steht: Entfernung und Gehalt.."},{"q":"Was empfiehlt Pablo?","choices":["Sofort kündigen.","Immer das höchste Gehalt wählen.","Arbeitszeiten und Kollegen berücksichtigen."],"correct":2,"why":"Im Dialog steht: Arbeitszeiten und Kollegen berücksichtigen.."}],"tips":[{"title":"Si tuviera más tiempo","body":"Wörtlich: „Wenn ich mehr Zeit hätte.“ Natürlich: „Wenn ich mehr Zeit hätte.“ Tuviera steht hier für eine nur gedachte Situation. Dazu passt sería – „wäre“."}]},{"id":"basis4-7","title":"¿Es mejor vivir en la ciudad?","subtitle":"Basis 4 · Paket 7","deck_id":"palabra-basis-4","required":7,"description":"Meinungen respektvoll austauschen.","lines":[["Marcos","En mi opinión, es mejor vivir en una ciudad grande.","Meiner Meinung nach ist es besser, in einer großen Stadt zu wohnen."],["Lucía","No estoy de acuerdo. A mí me gusta más vivir en un pueblo.","Ich bin nicht einverstanden. Ich wohne lieber in einem Dorf."],["Marcos","¿Por qué? En la ciudad hay más oportunidades.","Warum? In der Stadt gibt es mehr Möglichkeiten."],["Lucía","Es verdad, pero también hay más ruido y estrés.","Das stimmt, aber es gibt dort auch mehr Lärm und Stress."],["Marcos","Tienes razón. Aunque para mí es importante tener muchas actividades cerca.","Du hast recht. Trotzdem ist es mir wichtig, viele Aktivitäten in der Nähe zu haben."],["Lucía","Desde mi punto de vista, la tranquilidad es más importante.","Aus meiner Sicht ist Ruhe wichtiger."],["Marcos","Bueno, depende de lo que necesite cada persona.","Na ja, es hängt davon ab, was jede Person braucht."]],"questions":[{"q":"Wer bevorzugt die Stadt?","choices":["Lucía.","Marcos.","Beide nur das Dorf."],"correct":1,"why":"Im Dialog steht: Marcos.."},{"q":"Was kritisiert Lucía an der Stadt?","choices":["Wenig Arbeit.","Zu wenige Läden.","Lärm und Stress."],"correct":2,"why":"Im Dialog steht: Lärm und Stress.."},{"q":"Was ist ihr gemeinsames Fazit?","choices":["Es hängt von den Bedürfnissen ab.","Alle sollten umziehen.","Dörfer sind immer besser."],"correct":0,"why":"Im Dialog steht: Es hängt von den Bedürfnissen ab.."}],"tips":[{"title":"Tienes razón","body":"Wörtlich: „Du hast Recht/Vernunft.“ Natürlich: „Du hast recht.“ Auch hier benutzt Spanisch tener, wo Deutsch recht haben als feste Wendung kennt."}]},{"id":"basis4-8","title":"¿Coche o transporte público?","subtitle":"Basis 4 · Paket 8","deck_id":"palabra-basis-4","required":8,"description":"Argumente in einer Diskussion verstehen.","lines":[["Ana","Creo que deberíamos usar más el transporte público.","Ich denke, wir sollten mehr öffentliche Verkehrsmittel nutzen."],["Pablo","Estoy de acuerdo, pero a veces el coche es más cómodo.","Ich stimme zu, aber manchmal ist das Auto bequemer."],["Ana","Sí, aunque también es más caro. Además, hay mucho tráfico.","Ja, obwohl es auch teurer ist. Außerdem gibt es viel Verkehr."],["Pablo","Por otro lado, los autobuses no siempre son puntuales.","Andererseits sind Busse nicht immer pünktlich."],["Ana","Es verdad. Sin embargo, en las ciudades grandes hay buenas conexiones.","Das stimmt. Allerdings gibt es in großen Städten gute Verbindungen."],["Pablo","Entonces depende de dónde vivas.","Dann hängt es davon ab, wo man wohnt."],["Ana","Exacto. En resumen, necesitamos buenas alternativas al coche.","Genau. Zusammenfassend brauchen wir gute Alternativen zum Auto."]],"questions":[{"q":"Was befürwortet Ana?","choices":["Mehr Autos.","Weniger Busse.","Mehr öffentliche Verkehrsmittel."],"correct":2,"why":"Im Dialog steht: Mehr öffentliche Verkehrsmittel.."},{"q":"Was kritisiert Pablo?","choices":["Busse sind nicht immer pünktlich.","Züge sind zu schnell.","Fahrräder sind zu billig."],"correct":0,"why":"Im Dialog steht: Busse sind nicht immer pünktlich.."},{"q":"Worin stimmen beide überein?","choices":["Autos sollten verboten werden.","Gute Alternativen zum Auto sind wichtig.","Niemand braucht Verkehrsmittel."],"correct":1,"why":"Im Dialog steht: Gute Alternativen zum Auto sind wichtig.."}],"tips":[{"title":"Sin embargo","body":"Wörtlich: „Jedoch.“ (keine hilfreiche Einzelwortzerlegung) Natürlich: „Allerdings / jedoch.“ Merke dir sin embargo als feste Gegensatz-Wendung."}]},{"id":"basis4-9","title":"Una amistad de muchos años","subtitle":"Basis 4 · Paket 9","deck_id":"palabra-basis-4","required":9,"description":"Über eine langjährige Freundschaft sprechen.","lines":[["Lucía","¿Desde cuándo conoces a Carlos?","Seit wann kennst du Carlos?"],["Elena","Desde la escuela. Somos amigos desde hace más de quince años.","Seit der Schule. Wir sind seit über 15 Jahren befreundet."],["Lucía","¡Qué bonito! ¿Siempre os habéis llevado bien?","Wie schön! Habt ihr euch immer gut verstanden?"],["Elena","Casi siempre. A veces discutíamos, pero nunca perdimos el contacto.","Fast immer. Manchmal stritten wir, aber wir verloren nie den Kontakt."],["Lucía","¿Y todavía quedáis a menudo?","Und trefft ihr euch immer noch oft?"],["Elena","Sí. Aunque vivimos en ciudades diferentes, intentamos vernos cada mes.","Ja. Obwohl wir in verschiedenen Städten wohnen, versuchen wir uns jeden Monat zu sehen."],["Lucía","Eso es una amistad de verdad.","Das ist echte Freundschaft."],["Elena","Sí, nos apoyamos mutuamente.","Ja, wir unterstützen uns gegenseitig."]],"questions":[{"q":"Seit wann kennen sie sich?","choices":["Seit der Schulzeit.","Seit letzter Woche.","Seit dem Urlaub."],"correct":0,"why":"Im Dialog steht: Seit der Schulzeit.."},{"q":"Haben sie sich früher gestritten?","choices":["Nein, nie.","Ja, manchmal.","Nur im Urlaub."],"correct":1,"why":"Im Dialog steht: Ja, manchmal.."},{"q":"Wie oft versuchen sie sich zu sehen?","choices":["Jeden Tag.","Einmal im Jahr.","Jeden Monat."],"correct":2,"why":"Im Dialog steht: Jeden Monat.."}],"tips":[{"title":"Nos llevamos bien","body":"Wörtlich: „Wir kommen gut miteinander aus.“ Natürlich: „Wir verstehen uns gut.“ Llevarse bien ist eine feste Wendung für eine gute Beziehung."}]},{"id":"basis4-10","title":"Gracias por estar ahí","subtitle":"Basis 4 · Paket 10","deck_id":"palabra-basis-4","required":10,"description":"Gefühle und Vertrauen ausdrücken.","lines":[["Ana","Pablo, quería darte las gracias por escucharme ayer.","Pablo, ich wollte dir danken, dass du mir gestern zugehört hast."],["Pablo","No tienes que darme las gracias. Para eso están los amigos.","Du musst mir nicht danken. Dafür sind Freunde da."],["Ana","Lo sé, pero últimamente he estado muy preocupada.","Ich weiß, aber in letzter Zeit war ich sehr besorgt."],["Pablo","Me alegro de que hoy te sientas mejor.","Ich freue mich, dass du dich heute besser fühlst."],["Ana","Sí. Hablar contigo me ayuda mucho.","Ja. Mit dir zu reden hilft mir sehr."],["Pablo","Puedes confiar en mí. Y si necesitas algo, estoy aquí.","Du kannst mir vertrauen. Und wenn du etwas brauchst, bin ich da."],["Ana","Gracias. Es importante tener amigos que te entiendan.","Danke. Es ist wichtig, Freunde zu haben, die einen verstehen."],["Pablo","¡Y yo tengo mucha suerte de tenerte como amiga!","Und ich habe großes Glück, dich als Freundin zu haben!"]],"questions":[{"q":"Wofür bedankt sich Ana?","choices":["Für ein Geschenk.","Dass Pablo ihr zugehört hat.","Für eine Reise."],"correct":1,"why":"Im Dialog steht: Dass Pablo ihr zugehört hat.."},{"q":"Wie fühlt sie sich heute?","choices":["Schlechter.","Wütend.","Besser."],"correct":2,"why":"Im Dialog steht: Besser.."},{"q":"Was versichert Pablo?","choices":["Sie kann ihm vertrauen.","Er zieht morgen um.","Er hat keine Zeit."],"correct":0,"why":"Im Dialog steht: Sie kann ihm vertrauen.."}],"tips":[{"title":"Me alegro de que…","body":"Wörtlich: „Ich freue mich darüber, dass …“ Natürlich: „Ich freue mich, dass …“ Nach dieser Gefühlsreaktion steht der Subjuntivo: te sientas."}]},{"id":"basis5-1","title":"Una tarde inesperada","subtitle":"Basis 5 · Paket 1","deck_id":"palabra-basis-5","required":1,"description":"Eine Geschichte mit einer Wendung verstehen.","lines":[["Ana","¿Qué tal el fin de semana? Me dijiste que ibas a visitar a tu hermana.","Wie war das Wochenende? Du sagtest, du wolltest deine Schwester besuchen."],["Pablo","Sí, pero al principio todo salió mal. Perdí el tren y tuve que esperar una hora.","Ja, aber am Anfang ging alles schief. Ich verpasste den Zug und musste eine Stunde warten."],["Ana","¡Qué mala suerte!","Was für ein Pech!"],["Pablo","Y justo entonces empezó a llover muchísimo.","Und genau da fing es heftig an zu regnen."],["Ana","¿Y qué hiciste?","Und was hast du gemacht?"],["Pablo","Resulta que un amigo estaba cerca de la estación. Me llamó y fuimos a tomar un café.","Es stellte sich heraus, dass ein Freund in der Nähe des Bahnhofs war. Er rief mich an und wir gingen einen Kaffee trinken."],["Ana","¡Qué casualidad!","Was für ein Zufall!"],["Pablo","Al final llegué tarde a casa de mi hermana, pero pasamos una tarde estupenda.","Am Ende kam ich spät bei meiner Schwester an, aber wir verbrachten einen wunderbaren Nachmittag."]],"questions":[{"q":"Welche zwei Probleme hatte Pablo?","choices":["Er verlor den Pass und sein Handy.","Seine Schwester war verreist.","Er verpasste den Zug und es regnete stark."],"correct":2,"why":"Im Dialog steht: Er verpasste den Zug und es regnete stark.."},{"q":"Wer rief Pablo an?","choices":["Ein Freund in der Nähe des Bahnhofs.","Ein Polizist.","Seine Lehrerin."],"correct":0,"why":"Im Dialog steht: Ein Freund in der Nähe des Bahnhofs.."},{"q":"Wie endete der Tag?","choices":["Er blieb allein am Bahnhof.","Mit einem schönen Nachmittag bei seiner Schwester.","Er fuhr nicht mehr los."],"correct":1,"why":"Im Dialog steht: Mit einem schönen Nachmittag bei seiner Schwester.."}],"tips":[{"title":"Resulta que…","body":"Wörtlich: „Es ergibt sich, dass …“ Natürlich: „Es stellte sich heraus, dass …“ Damit kann man einer Geschichte eine unerwartete Wendung geben."}]},{"id":"basis5-2","title":"¡No me lo podía creer!","subtitle":"Basis 5 · Paket 2","deck_id":"palabra-basis-5","required":2,"description":"Eine Überraschung am Flughafen.","lines":[["Lucía","No sabes lo que me pasó ayer.","Du glaubst nicht, was mir gestern passiert ist."],["Elena","¡Cuenta, cuenta!","Erzähl, erzähl!"],["Lucía","Estaba en el aeropuerto y me di cuenta de que no tenía el pasaporte.","Ich war am Flughafen und bemerkte, dass ich meinen Reisepass nicht hatte."],["Elena","¡No me digas! ¿Qué hiciste?","Sag bloß! Was hast du gemacht?"],["Lucía","Busqué en todas mis bolsas, pero no lo encontraba. Pensé que me quedaría sin vuelo.","Ich suchte in all meinen Taschen, fand ihn aber nicht. Ich dachte, ich würde meinen Flug verpassen."],["Elena","¡Qué horror!","Wie schrecklich!"],["Lucía","Al final resultó que estaba dentro de mi chaqueta.","Am Ende stellte sich heraus, dass er in meiner Jacke war."],["Elena","¡Menos mal! ¿Llegaste a tiempo?","Zum Glück! Bist du rechtzeitig angekommen?"],["Lucía","Sí, por suerte. Pero ¡qué susto!","Ja, zum Glück. Aber was für ein Schreck!"]],"questions":[{"q":"Was glaubte Lucía zu vermissen?","choices":["Ihren Reisepass.","Ihre Jacke.","Ihre Fahrkarte."],"correct":0,"why":"Im Dialog steht: Ihren Reisepass.."},{"q":"Wo war der Gegenstand tatsächlich?","choices":["Im Flugzeug.","In ihrer Jacke.","Im Taxi."],"correct":1,"why":"Im Dialog steht: In ihrer Jacke.."},{"q":"Hat sie den Flug erreicht?","choices":["Nein, sie blieb daheim.","Sie weiß es noch nicht.","Ja, rechtzeitig."],"correct":2,"why":"Im Dialog steht: Ja, rechtzeitig.."}],"tips":[{"title":"Me di cuenta de que…","body":"Wörtlich: „Ich gab mir Rechenschaft darüber, dass …“ Natürlich: „Mir wurde klar, dass …“ Darse cuenta de heißt als Einheit: bemerken, erkennen."}]},{"id":"basis5-3","title":"¿Qué harías en mi lugar?","subtitle":"Basis 5 · Paket 3","deck_id":"palabra-basis-5","required":3,"description":"Ratschläge zu einer Arbeitsentscheidung.","lines":[["Marcos","Estoy pensando en cambiar de trabajo, pero no estoy seguro.","Ich denke darüber nach, den Job zu wechseln, aber bin nicht sicher."],["Ana","¿Por qué quieres cambiar?","Warum möchtest du wechseln?"],["Marcos","Mi trabajo actual es interesante, pero tengo muy poco tiempo libre.","Meine jetzige Arbeit ist interessant, aber ich habe sehr wenig Freizeit."],["Ana","Yo que tú, hablaría primero con tu jefe.","An deiner Stelle würde ich zuerst mit deinem Chef reden."],["Marcos","¿Crees que merece la pena?","Glaubst du, es lohnt sich?"],["Ana","Sí. Quizá puedas cambiar tu horario. Y si no, siempre puedes buscar otro empleo.","Ja. Vielleicht kannst du deine Arbeitszeiten ändern. Und sonst kannst du immer noch eine andere Stelle suchen."],["Marcos","Tienes razón. No quiero tomar una decisión demasiado rápido.","Du hast recht. Ich möchte nicht zu schnell entscheiden."],["Ana","Exacto. Tómate tu tiempo.","Genau. Lass dir Zeit."]],"questions":[{"q":"Warum denkt Marcos über einen Jobwechsel nach?","choices":["Er mag seine Kollegen nicht.","Er hat zu wenig Freizeit.","Sein Vertrag ist schon abgelaufen."],"correct":1,"why":"Im Dialog steht: Er hat zu wenig Freizeit.."},{"q":"Was empfiehlt Ana zuerst?","choices":["Sofort kündigen.","Eine Reise machen.","Mit dem Chef sprechen."],"correct":2,"why":"Im Dialog steht: Mit dem Chef sprechen.."},{"q":"Warum soll Marcos sich Zeit lassen?","choices":["Er möchte nicht überstürzt entscheiden.","Er muss zuerst Spanisch lernen.","Er wartet auf sein Ticket."],"correct":0,"why":"Im Dialog steht: Er möchte nicht überstürzt entscheiden.."}],"tips":[{"title":"Yo que tú…","body":"Wörtlich: „Ich, wenn ich du wäre …“ Natürlich: „An deiner Stelle …“ Darauf folgt oft ein Konditional: hablaría – „ich würde reden“."}]},{"id":"basis5-4","title":"¿Y si nos vamos de viaje?","subtitle":"Basis 5 · Paket 4","deck_id":"palabra-basis-5","required":4,"description":"Eine Reise unter Bedingungen planen.","lines":[["Elena","¿Y si hacemos un viaje a México el próximo verano?","Wie wäre es, wenn wir nächsten Sommer nach Mexiko reisen?"],["Carlos","¡Me encantaría! Pero dependerá de cuánto dinero tengamos.","Sehr gerne! Aber es hängt davon ab, wie viel Geld wir haben."],["Elena","Si ahorráramos un poco cada mes, podríamos hacerlo.","Wenn wir jeden Monat etwas sparen würden, könnten wir es schaffen."],["Carlos","Es verdad. Aunque habría que comprar los billetes con tiempo.","Das stimmt. Allerdings müsste man die Tickets frühzeitig kaufen."],["Elena","Sí. Y por si acaso, podemos buscar vuelos que se puedan cambiar.","Ja. Und vorsichtshalber können wir nach umbuchbaren Flügen suchen."],["Carlos","Me parece bien, siempre que no sean demasiado caros.","Das klingt gut, sofern sie nicht zu teuer sind."],["Elena","Entonces, ¿empezamos a planearlo?","Fangen wir also an zu planen?"],["Carlos","¡Claro! Pase lo que pase, al menos lo intentaremos.","Klar! Was auch passiert, wir werden es wenigstens versuchen."]],"questions":[{"q":"Wohin möchten die beiden reisen?","choices":["Nach Frankreich.","Nach Japan.","Nach Mexiko."],"correct":2,"why":"Im Dialog steht: Nach Mexiko.."},{"q":"Was ist die größte Unsicherheit?","choices":["Ob sie genug Geld haben.","Ob sie Urlaub mögen.","Ob sie fliegen können."],"correct":0,"why":"Im Dialog steht: Ob sie genug Geld haben.."},{"q":"Welche Vorsichtsmaßnahme planen sie?","choices":["Nur Bargeld mitnehmen.","Umbuchbare Flüge suchen.","Ohne Koffer reisen."],"correct":1,"why":"Im Dialog steht: Umbuchbare Flüge suchen.."}],"tips":[{"title":"Por si acaso","body":"Wörtlich: „Für den Fall, dass …“ Natürlich: „Vorsichtshalber / für alle Fälle.“ Eine häufige Wendung, wenn man Risiken berücksichtigen möchte."}]},{"id":"basis5-5","title":"Ojalá pudiera ir contigo","subtitle":"Basis 5 · Paket 5","deck_id":"palabra-basis-5","required":5,"description":"Wünsche für einen neuen Lebensabschnitt.","lines":[["Lucía","Me han ofrecido un trabajo en Barcelona.","Mir wurde eine Stelle in Barcelona angeboten."],["Ana","¡Qué alegría! ¿Vas a aceptarlo?","Was für eine Freude! Wirst du sie annehmen?"],["Lucía","Creo que sí. Me hace mucha ilusión vivir allí.","Ich glaube schon. Ich freue mich sehr darauf, dort zu leben."],["Ana","¡Ojalá pudiera ir contigo! Siempre he querido vivir cerca del mar.","Wenn ich doch mitkommen könnte! Ich wollte schon immer am Meer wohnen."],["Lucía","Pues ven a visitarme cuando quieras.","Dann besuch mich, wann immer du willst."],["Ana","¡Me encantaría! Espero que te vaya muy bien.","Sehr gerne! Ich hoffe, es läuft richtig gut für dich."],["Lucía","Gracias. Y espero que podamos vernos a menudo.","Danke. Und ich hoffe, dass wir uns oft sehen können."],["Ana","¡Seguro que sí!","Ganz bestimmt!"]],"questions":[{"q":"Was wurde Lucía angeboten?","choices":["Ein Job in Barcelona.","Ein kostenloser Flug.","Eine Wohnung in Madrid."],"correct":0,"why":"Im Dialog steht: Ein Job in Barcelona.."},{"q":"Warum freut sich Lucía?","choices":["Sie möchte ihr Studium abbrechen.","Sie möchte dort leben.","Sie hat Urlaub gewonnen."],"correct":1,"why":"Im Dialog steht: Sie möchte dort leben.."},{"q":"Was wünscht sich Ana?","choices":["Sie möchte nicht reisen.","Sie möchte die Stelle selbst.","Sie würde gern mitkommen."],"correct":2,"why":"Im Dialog steht: Sie würde gern mitkommen.."}],"tips":[{"title":"Ojalá pudiera…","body":"Wörtlich: „Wenn ich doch könnte …!“ Natürlich: „Wenn ich doch könnte …!“ Ojalá hat arabische Wurzeln und drückt einen starken Wunsch aus."}]},{"id":"basis5-6","title":"¿Dónde estará Marcos?","subtitle":"Basis 5 · Paket 6","deck_id":"palabra-basis-5","required":6,"description":"Vermutungen und ihre Auflösung.","lines":[["Elena","¿Has visto a Marcos? Hemos quedado a las cinco y todavía no está aquí.","Hast du Marcos gesehen? Wir waren um fünf verabredet, aber er ist noch nicht da."],["Carlos","No. Puede que haya perdido el autobús.","Nein. Vielleicht hat er den Bus verpasst."],["Elena","Es posible, pero normalmente es muy puntual.","Möglich, aber normalerweise ist er sehr pünktlich."],["Carlos","Quizá tenga un problema con el móvil.","Vielleicht hat er ein Problem mit dem Handy."],["Elena","¿Crees que deberíamos llamarlo?","Glaubst du, wir sollten ihn anrufen?"],["Carlos","Sí, aunque puede que no tenga batería.","Ja, obwohl sein Akku vielleicht leer ist."],["Elena","Espera, me acaba de escribir. Dice que está en otra cafetería.","Warte, er hat mir gerade geschrieben. Er sagt, er sei in einem anderen Café."],["Carlos","¡Vaya! Al parecer, hemos entendido lugares diferentes.","Ach! Offenbar haben wir unterschiedliche Treffpunkte verstanden."]],"questions":[{"q":"Warum warten Elena und Carlos?","choices":["Das Café öffnet erst später.","Marcos ist nicht am Treffpunkt.","Sie haben kein Geld."],"correct":1,"why":"Im Dialog steht: Marcos ist nicht am Treffpunkt.."},{"q":"Was vermuten sie?","choices":["Er ist schon im Urlaub.","Er arbeitet heute Nacht.","Er hat den Bus verpasst oder ein Handyproblem."],"correct":2,"why":"Im Dialog steht: Er hat den Bus verpasst oder ein Handyproblem.."},{"q":"Was ist tatsächlich passiert?","choices":["Marcos wartet in einem anderen Café.","Sein Bus ist kaputt.","Er hat sein Handy verloren."],"correct":0,"why":"Im Dialog steht: Marcos wartet in einem anderen Café.."}],"tips":[{"title":"Puede que haya perdido","body":"Wörtlich: „Es kann sein, dass er verloren hat.“ Natürlich: „Vielleicht hat er verpasst.“ Puede que drückt Unsicherheit aus; danach folgt der Subjuntivo."}]},{"id":"basis5-7","title":"Una conversación espontánea","subtitle":"Basis 5 · Paket 7","deck_id":"palabra-basis-5","required":7,"description":"Natürliche Gesprächssignale verstehen.","lines":[["Ana","Oye, ¿qué vas a hacer este fin de semana?","Sag mal, was machst du dieses Wochenende?"],["Pablo","Pues… todavía no lo tengo claro. Quizá vaya a visitar a mi hermano.","Also ... ich bin noch nicht sicher. Vielleicht besuche ich meinen Bruder."],["Ana","¡Ah, claro! Vive en Valencia, ¿verdad?","Ach ja! Er wohnt in Valencia, oder?"],["Pablo","Sí. Bueno, ahora vive cerca de Valencia, en un pueblo pequeño.","Ja. Na ja, jetzt wohnt er in einem kleinen Dorf nahe Valencia."],["Ana","Ya veo. Por cierto, ¿cómo está su hija?","Ach so. Übrigens, wie geht es seiner Tochter?"],["Pablo","Muy bien. Está aprendiendo a caminar.","Sehr gut. Sie lernt gerade laufen."],["Ana","¡Qué bonito! A propósito, ¿te apetece tomar un café mañana?","Wie schön! Übrigens, hast du morgen Lust auf einen Kaffee?"],["Pablo","¡Claro que sí!","Na klar!"]],"questions":[{"q":"Was plant Pablo möglicherweise?","choices":["Zum Konzert gehen.","Ein Auto kaufen.","Seinen Bruder besuchen."],"correct":2,"why":"Im Dialog steht: Seinen Bruder besuchen.."},{"q":"Wo lebt Pablos Bruder?","choices":["In einem kleinen Dorf bei Valencia.","In Berlin.","Am Flughafen."],"correct":0,"why":"Im Dialog steht: In einem kleinen Dorf bei Valencia.."},{"q":"Was vereinbaren Ana und Pablo?","choices":["Am Samstag arbeiten.","Morgen Kaffee trinken.","Heute Abend tanzen."],"correct":1,"why":"Im Dialog steht: Morgen Kaffee trinken.."}],"tips":[{"title":"Es que…","body":"Wörtlich: „Es ist, dass …“ Natürlich: „Es ist nur so, dass …“ Die feste Wendung leitet oft eine vorsichtige Erklärung ein; sie muss nicht in jeder Unterhaltung vorkommen."}]},{"id":"basis5-8","title":"Un pequeño malentendido","subtitle":"Basis 5 · Paket 8","deck_id":"palabra-basis-5","required":8,"description":"Missverständnisse höflich klären.","lines":[["Marcos","Perdona que te moleste, Elena. ¿Te importaría ayudarme con una cosa?","Entschuldige, dass ich störe, Elena. Würde es dir etwas ausmachen, mir bei etwas zu helfen?"],["Elena","Claro. ¿Qué necesitas?","Natürlich. Was brauchst du?"],["Marcos","Dijiste que el proyecto estaba terminado, pero todavía falta una parte.","Du sagtest, das Projekt sei fertig, aber es fehlt noch ein Teil."],["Elena","Ah, creo que ha habido un malentendido.","Ah, ich glaube, es gab ein Missverständnis."],["Marcos","¿A qué te refieres?","Was meinst du damit?"],["Elena","Lo que quería decir es que mi parte estaba terminada, no todo el proyecto.","Ich wollte sagen, dass mein Teil fertig war, nicht das ganze Projekt."],["Marcos","¡Ah, ahora entiendo! Perdona, no te había entendido bien.","Ah, jetzt verstehe ich! Entschuldigung, ich hatte dich falsch verstanden."],["Elena","No pasa nada. Podemos terminarlo juntos.","Macht nichts. Wir können es gemeinsam fertigstellen."]],"questions":[{"q":"Worin bestand das Missverständnis?","choices":["Elena meinte nur ihren Teil des Projekts.","Das Projekt wurde abgesagt.","Marcos hatte Urlaub."],"correct":0,"why":"Im Dialog steht: Elena meinte nur ihren Teil des Projekts.."},{"q":"Was war bereits fertig?","choices":["Das gesamte Projekt.","Elenas Teil.","Überhaupt nichts."],"correct":1,"why":"Im Dialog steht: Elenas Teil.."},{"q":"Wie lösen sie die Situation?","choices":["Sie streiten und gehen.","Sie verschieben das Projekt um ein Jahr.","Sie arbeiten gemeinsam weiter."],"correct":2,"why":"Im Dialog steht: Sie arbeiten gemeinsam weiter.."}],"tips":[{"title":"¿Te importaría…?","body":"Wörtlich: „Würde es dir etwas ausmachen …?“ Natürlich: „Würde es dir etwas ausmachen …?“ Der Konditional von importar klingt sehr höflich."}]},{"id":"basis5-9","title":"Lo que he aprendido","subtitle":"Basis 5 · Paket 9","deck_id":"palabra-basis-5","required":9,"description":"Persönliche Erfahrungen reflektieren.","lines":[["Lucía","Si pudieras volver a tener veinte años, ¿harías algo diferente?","Wenn du wieder zwanzig sein könntest, würdest du etwas anders machen?"],["Carlos","Quizá sí. Antes tenía miedo de cometer errores y por eso perdí algunas oportunidades.","Vielleicht. Früher hatte ich Angst vor Fehlern und verpasste deshalb einige Chancen."],["Lucía","¿Y qué has aprendido?","Und was hast du gelernt?"],["Carlos","Que es importante arriesgarse de vez en cuando. Aunque las cosas salgan mal, siempre puedes aprender algo.","Dass es wichtig ist, ab und zu Risiken einzugehen. Auch wenn Dinge schiefgehen, kann man immer etwas lernen."],["Lucía","Estoy de acuerdo. Yo también he cambiado mucho con los años.","Ich stimme zu. Auch ich habe mich über die Jahre stark verändert."],["Carlos","¿En qué sentido?","Inwiefern?"],["Lucía","Ahora valoro más mi tiempo y las personas que quiero.","Heute schätze ich meine Zeit und die Menschen, die ich liebe, mehr."],["Carlos","Eso es lo importante. Hay que seguir adelante.","Das ist das Wichtigste. Man muss weitermachen."]],"questions":[{"q":"Was bereut Carlos?","choices":["Dass er zu viel reiste.","Dass er aus Angst Chancen verpasst hat.","Dass er nicht gekocht hat."],"correct":1,"why":"Im Dialog steht: Dass er aus Angst Chancen verpasst hat.."},{"q":"Was hat Carlos gelernt?","choices":["Man darf nie Risiken eingehen.","Arbeit ist alles.","Aus Fehlern kann man lernen."],"correct":2,"why":"Im Dialog steht: Aus Fehlern kann man lernen.."},{"q":"Was schätzt Lucía heute besonders?","choices":["Ihre Zeit und ihre Liebsten.","Teure Kleidung.","Große Autos."],"correct":0,"why":"Im Dialog steht: Ihre Zeit und ihre Liebsten.."}],"tips":[{"title":"Seguir adelante","body":"Wörtlich: „Weiter vorwärtsgehen.“ Natürlich: „Weitermachen / nach vorne schauen.“ Adelante heißt vorwärts; die Wendung kann auch im übertragenen Sinn Mut machen."}]},{"id":"basis5-10","title":"¿Qué es lo más importante?","subtitle":"Basis 5 · Paket 10","deck_id":"palabra-basis-5","required":10,"description":"Ein persönliches Gespräch verstehen.","lines":[["Ana","Si lo piensas bien, ¿qué es lo más importante para ti en la vida?","Wenn du genauer darüber nachdenkst, was ist dir im Leben am wichtigsten?"],["Pablo","Buena pregunta. Antes pensaba que lo más importante era tener éxito en el trabajo.","Gute Frage. Früher dachte ich, dass beruflicher Erfolg das Wichtigste sei."],["Ana","¿Y ahora?","Und jetzt?"],["Pablo","Ahora creo que es más importante tener tiempo para las personas que quiero.","Jetzt glaube ich, es ist wichtiger, Zeit für die Menschen zu haben, die ich liebe."],["Ana","Estoy de acuerdo. Aunque también necesitamos dinero para vivir.","Ich stimme zu. Obwohl wir auch Geld zum Leben brauchen."],["Pablo","Claro. Al fin y al cabo, se trata de encontrar un equilibrio.","Natürlich. Letzten Endes geht es darum, ein Gleichgewicht zu finden."],["Ana","Sí. En el fondo, lo que más me importa es estar contenta con mi vida.","Ja. Im Grunde ist mir am wichtigsten, mit meinem Leben zufrieden zu sein."],["Pablo","Exactamente. Y seguir aprendiendo cosas nuevas.","Genau. Und weiter Neues lernen."]],"questions":[{"q":"Was war Pablo früher besonders wichtig?","choices":["Sport.","Reisen.","Beruflicher Erfolg."],"correct":2,"why":"Im Dialog steht: Beruflicher Erfolg.."},{"q":"Was denkt er heute?","choices":["Zeit für seine Liebsten ist wichtiger.","Nur Geld zählt.","Arbeit ist sinnlos."],"correct":0,"why":"Im Dialog steht: Zeit für seine Liebsten ist wichtiger.."},{"q":"Worin stimmen die beiden überein?","choices":["Man sollte nie arbeiten.","Es kommt auf ein gutes Gleichgewicht an.","Freizeit ist unwichtig."],"correct":1,"why":"Im Dialog steht: Es kommt auf ein gutes Gleichgewicht an.."}],"tips":[{"title":"Al fin y al cabo","body":"Wörtlich: „Am Ende und am Abschluss.“ Natürlich: „Letzten Endes.“ Ein fester Ausdruck, um eine Überlegung zusammenzufassen."}]}];
let dataRef,saveFn,current=null,selected={},checked={},revealed=new Set(),tips=new Set();
const introduced=(data,l)=>data.words.filter(w=>w.deck_id===(l.deck_id||'palabra-basis-1')&&w.package_in_deck===l.required&&!!w.progress?.passive?.introducedOn).length;
const unlocked=(data,l)=>window.PalabraDev?.enabled()||introduced(data,l)>=20;
function renderHome(data){const el=$('dialogueHomeList');if(!el)return;const done=lessons.filter(l=>data.dialogues?.[l.id]?.completed).length;const ready=lessons.filter(l=>unlocked(data,l)).length;el.innerHTML=`<p class="dialogue-muted">${done} von ${lessons.length} Dialogen abgeschlossen · ${ready} verfügbar${window.PalabraDev?.enabled()?' (Entwicklermodus)':''}</p>`}
function render(data,save){dataRef=data;saveFn=save;current=null;renderList()}
const DECK_LABELS=['Erste Gespräche','Mein Alltag','Unterwegs & Reisen','Erlebnisse & Beziehungen','Freies Kommunizieren'];
const GROUP_NAMES=[
 ['Begrüßen & Kennenlernen','Im Café','Verabredungen','Familie & Freizeit','Unterwegs in der Stadt'],
 ['Mein Tagesablauf','Im Supermarkt','Mein Zuhause','Arbeit & Studium','Kochen & Essen'],
 ['Im Restaurant','Reisen & Verkehr','Im Hotel','Kleidung kaufen','Probleme lösen'],
 ['Erlebnisse & Erinnerungen','Gefühle & Wohlbefinden','Pläne & Entscheidungen','Meinungen & Diskussionen','Freundschaft & Beziehungen'],
 ['Geschichten erzählen','Ratschläge & Bedingungen','Wünsche & Vermutungen','Natürlich sprechen','Persönliche Entwicklung']
];
let openDeckGroup=1,openTopicGroup='1-1';
function renderList(){window.PalabraGrammarAudio?.stop();
 const el=$('dialogueArea');if(!el)return;
 const totals=lessons.length;
 const completed=lessons.filter(l=>dataRef.dialogues?.[l.id]?.completed).length;
 const accessible=lessons.filter(l=>unlocked(dataRef,l)).length;
 let html=`<div class="panel"><h2>Gespräche verstehen</h2><p class="dialogue-muted">${completed} von ${totals} abgeschlossen · ${accessible} verfügbar${window.PalabraDev?.enabled()?' · Entwicklermodus':''}</p><p class="dialogue-muted">Wähle ein Basisdeck und klappe anschließend deinen Themenblock auf. Jede Einheit enthält zwei Dialoge. Keine Auswirkung auf das Vokabel-SRS.</p>`;
 for(let d=1;d<=5;d++){
  const ls=lessons.filter(l=>l.deck_id===`palabra-basis-${d}` || (!l.deck_id&&d===1));
  const done=ls.filter(l=>dataRef.dialogues?.[l.id]?.completed).length;
  html+=`<details class="dialogue-deck-group" data-deckgroup="${d}" ${openDeckGroup===d?'open':''}><summary><span class="dialogue-group-heading"><span class="dialogue-group-kicker">BASIS ${d}</span><strong>${esc(DECK_LABELS[d-1])}</strong></span><span class="dialogue-count">${done}/${ls.length} ✓</span></summary><div class="dialogue-deck-body">`;
  for(let t=1;t<=5;t++){
   const from=(t-1)*2+1,related=ls.filter(l=>l.required===from||l.required===from+1);
   const doneHere=related.filter(l=>dataRef.dialogues?.[l.id]?.completed).length;
   const unlockedHere=related.filter(l=>unlocked(dataRef,l)).length;
   const groupKey=`${d}-${t}`;
   html+=`<details class="dialogue-topic-group" data-topicgroup="${groupKey}" ${openTopicGroup===groupKey?'open':''}><summary><span class="dialogue-topic-name">${esc(GROUP_NAMES[d-1][t-1])}<small>Pakete ${from}–${from+1}</small></span><span class="dialogue-topic-status">${doneHere}/2 ✓ · ${unlockedHere}/2 🔓</span></summary><div class="dialogue-topic-body">`;
   for(const l of related){
    const i=lessons.indexOf(l),open=unlocked(dataRef,l),finished=dataRef.dialogues?.[l.id]?.completed;
    html+=`<div class="dialogue-entry"><div class="dialogue-entry-head"><strong>${esc(l.title)}</strong><span class="dialogue-entry-status">${finished?'✓ Erledigt':open?'🔓 Frei':'🔒 Gesperrt'}</span></div><p class="dialogue-muted">Paket ${l.required} · ${esc(l.description)}</p>${!open?`<p class="dialogue-muted">Noch ${Math.max(0,20-introduced(dataRef,l))} Wörter aus Paket ${l.required} einführen.</p>`:''}<button class="${open?'primary':'secondary'}" data-start="${i}" ${!open?'disabled':''}>${finished?'Erneut lesen ↻':'Gespräch lesen →'}</button></div>`;
   }
   html+='</div></details>';
  }
  html+='</div></details>';
 }
 html+='</div>';el.innerHTML=html;
 el.querySelectorAll('[data-start]').forEach(btn=>btn.onclick=()=>{const lesson=lessons[Number(btn.dataset.start)];openDeckGroup=Number((lesson.deck_id||'palabra-basis-1').split('-').pop());openTopicGroup=`${openDeckGroup}-${Math.ceil(lesson.required/2)}`;start(Number(btn.dataset.start))});
 el.querySelectorAll('[data-deckgroup]').forEach(x=>x.addEventListener('toggle',()=>{if(x.open){openDeckGroup=Number(x.dataset.deckgroup);el.querySelectorAll('[data-deckgroup]').forEach(other=>{if(other!==x)other.open=false})}}));
 el.querySelectorAll('[data-topicgroup]').forEach(x=>x.addEventListener('toggle',()=>{if(x.open){openTopicGroup=x.dataset.topicgroup;const parent=x.closest('[data-deckgroup]');parent?.querySelectorAll('[data-topicgroup]').forEach(other=>{if(other!==x)other.open=false})}}));
}
function start(i){window.PalabraGrammarAudio?.stop();current=lessons[i];selected={};checked={};revealed=new Set();tips=new Set();renderReading()}
function bubbles(){return current.lines.map(([who,es,de],i)=>{const open=revealed.has(i),mine=i>0&&who!==current.lines[0][0];const marked=esc(es).replace(/⟦(.*?)⟧/g,(_,word)=>`${word} <button type="button" class="dialogue-inline-tip" data-inline-tip="0" aria-label="Sprachblick zu ${word} anzeigen" title="Sprachblick öffnen">!</button>`);return `<div class="chat-line ${mine?'mine':''}" data-dialogue-turn="${i}"><span class="chat-name">${esc(who)}</span><div class="chat-bubble">${marked}</div>${window.PalabraGrammarAudio?.hasTurn(current.id,i)?`<button type="button" class="chat-play-turn" data-dialogue-id="${esc(current.id)}" data-dialogue-line="${i}" aria-pressed="false" aria-label="Sprechblase ${i+1} von ${esc(who)} anhören">▶ Anhören</button>${window.PalabraGrammarAudio?.needsReview(current.id,i)?`<span class="dialogue-audio-qa" title="Automatische Plausibilitätsprüfung: diese Aufnahme bitte anhören und kontrollieren">Audio prüfen</span>`:``}`:``}<button class="chat-help" data-translation="${i}" aria-expanded="${open}" aria-label="${open?'Übersetzung verbergen':'Satz übersetzen'}">🌐 ${open?'Übersetzung verbergen':'Übersetzen'}</button>${open?`<div class="chat-translation">${esc(de)}</div>`:''}</div>`}).join('')}
function question(q,i){const done=checked[i],chosen=selected[i];return `<section class="reading-question"><div class="reading-question-number">FRAGE ${i+1} VON ${current.questions.length}</div><h3>${esc(q.q)}</h3><div class="reading-options">${q.choices.map((c,j)=>`<button class="dialogue-choice ${chosen===j?'selected':''} ${done&&j===q.correct?'correct':''} ${done&&chosen===j&&j!==q.correct?'incorrect':''}" data-question="${i}" data-choice="${j}" ${done?'disabled':''} aria-pressed="${chosen===j}"><span class="reading-choice-marker">${done&&j===q.correct?'✓':String.fromCharCode(65+j)}</span><span>${esc(c)}</span></button>`).join('')}</div>${done?`<div class="dialogue-feedback ${chosen===q.correct?'':'wrong'}"><strong>${chosen===q.correct?'¡Muy bien!':'Schau noch einmal hin!'}</strong><p>${esc(q.why)}</p></div>`:`<button class="primary reading-check" data-check="${i}" ${chosen===undefined?'disabled':''}>Antwort prüfen</button>`}</section>`}
function renderReading(){window.PalabraGrammarAudio?.stop();const el=$('dialogueArea');if(!el)return;const allDone=current.questions.every((_,i)=>checked[i]);el.innerHTML=`<div class="dialogue-top"><button class="text-btn" id="backDialogues">← Alle Dialoge</button><span class="dialogue-muted">${esc(current.subtitle)}</span></div><div class="panel"><div class="eyebrow">LESEVERSTÄNDNIS · ${esc(current.subtitle)}</div><h2>${esc(current.title)}</h2><p class="dialogue-muted">Höre den Dialog aus einzelnen Aufnahmen am Stück oder spiele eine Sprechblase separat ab. Die neuen V3-Einzelaufnahmen werden nacheinander abgespielt. Die frühere Gesamtaufnahme bleibt zum Vergleich verfügbar.</p>${window.PalabraGrammarAudio?.hasDialogue(current.id)?`<div class="dialogue-playback" role="group" aria-label="Dialog anhören"><button type="button" class="primary" data-dialogue-play="${esc(current.id)}" aria-pressed="false">▶ Dialog abspielen</button><button type="button" class="secondary" data-dialogue-play="${esc(current.id)}" data-dialogue-slow="true" aria-pressed="false">▶ 0,8×</button><button type="button" class="secondary" data-dialogue-pause disabled aria-pressed="false">⏸ Pause</button><span class="dialogue-playback-progress" role="status" aria-live="off" data-dialogue-progress></span></div><details class="dialogue-original"><summary>Originalaufnahme des ganzen Dialogs</summary><p>Die frühere vollständige Aufnahme ist zum Vergleichen weiter verfügbar.</p><button type="button" class="secondary" data-dialogue-play="${esc(current.id)}" data-dialogue-original="true">▶ Original anhören</button></details>`:``}<div class="reading-scene">${bubbles()}</div><div class="reading-section-heading"><h3>Hast du das Gespräch verstanden?</h3><p class="dialogue-muted">${Object.keys(checked).length} von ${current.questions.length} Fragen beantwortet</p></div>${current.questions.map(question).join('')}<section class="reading-insights"><h3>💡 Sprachblick</h3><p class="dialogue-muted">Freiwillige Erklärungen, wie Spanisch funktioniert.</p>${current.tips.map((t,i)=>`<div class="reading-insight"><button class="reading-insight-toggle" data-tip="${i}" aria-expanded="${tips.has(i)}"><span>${esc(t.title)}</span><span>${tips.has(i)?'−':'+'}</span></button>${tips.has(i)?`<p>${esc(t.body)}</p>`:''}</div>`).join('')}</section>${allDone?`<div class="reading-complete"><h3>¡Muy bien! 🎉</h3><p>Du hast ${current.questions.filter((q,i)=>selected[i]===q.correct).length} von ${current.questions.length} Fragen richtig beantwortet. Dein SRS-Fortschritt bleibt unverändert.</p><button class="primary" id="dialogueFinish">Gespräch abschließen ✓</button></div>`:''}</div>`;
$('backDialogues').onclick=renderList;
el.querySelectorAll('[data-translation]').forEach(b=>b.onclick=()=>{
 const i=Number(b.dataset.translation),line=b.closest('.chat-line');if(!line)return;
 if(revealed.has(i)){revealed.delete(i);line.querySelector('.chat-translation')?.remove()}
 else{revealed.add(i);const t=document.createElement('div');t.className='chat-translation';t.textContent=current.lines[i][2];line.appendChild(t)}
 b.setAttribute('aria-expanded',String(revealed.has(i)));
 b.setAttribute('aria-label',revealed.has(i)?'Übersetzung verbergen':'Satz übersetzen');
 b.textContent=revealed.has(i)?'🌐 Übersetzung verbergen':'🌐 Übersetzen';
});
el.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.question);if(checked[i])return;selected[i]=Number(b.dataset.choice);renderReading()});
el.querySelectorAll('[data-check]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.check);if(selected[i]===undefined)return;checked[i]=true;renderReading()});
el.querySelectorAll('[data-inline-tip]').forEach(b=>b.onclick=()=>{tips.add(Number(b.dataset.inlineTip));renderReading();const target=el.querySelector('.reading-insights');if(target)target.scrollIntoView({behavior:'smooth',block:'center'})});
el.querySelectorAll('[data-tip]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.tip);tips.has(i)?tips.delete(i):tips.add(i);renderReading()});
if(allDone)$('dialogueFinish').onclick=finish;
}
function finish(){window.PalabraGrammarAudio?.stop();if(window.PalabraDev?.enabled()){const el=$('dialogueArea');el.innerHTML=`<div class="panel dialogue-done"><div class="big-emoji">🧪</div><h2>Test abgeschlossen</h2><p>Entwicklermodus: Der Dialog wurde getestet, ohne den Lernfortschritt zu verändern.</p><button class="primary" id="dialogueAgain">Erneut lesen ↻</button><button class="secondary" id="dialogueOverview">Alle Dialoge ansehen</button></div>`;$('dialogueAgain').onclick=()=>start(lessons.indexOf(current));$('dialogueOverview').onclick=renderList;return;}if(!dataRef.dialogues)dataRef.dialogues={};dataRef.dialogues[current.id]={completed:true,lastCompleted:new Date().toISOString()};saveFn();const el=$('dialogueArea');el.innerHTML=`<div class="panel dialogue-done"><div class="big-emoji">🎉</div><h2>¡Excelente!</h2><p>Du hast „${esc(current.title)}“ gelesen und verstanden.</p><p class="dialogue-muted">Die Mini-Dialoge sind reine Verständnisübungen. Keine SRS-Wertung verändert.</p><button class="primary" id="dialogueAgain">Erneut lesen ↻</button><button class="secondary" id="dialogueOverview">Alle Dialoge ansehen</button></div>`;$('dialogueAgain').onclick=()=>start(lessons.indexOf(current));$('dialogueOverview').onclick=renderList;renderHome(dataRef)}
return{render,renderHome,getLesson:id=>lessons.find(x=>x.id===id)||null};})();
